INSERT INTO datasets (name, layer, cartridge, sources, sql_def, description, column_mapping, schedule, updated_at, workspace_id)
VALUES ($seed$costo_consultor_mensual$seed$, $seed$gold$seed$, $seed$replicon$seed$, $seed$["raw/replicon/TimeEntry"]$seed$::jsonb, $seed$WITH te AS (
    SELECT userid, username,
        
        DATE_TRUNC('month', CAST(entrydate AS DATE)) AS mes,
        SUM(durationhours) AS horas_ejecutadas
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_timeentry_latest/data.parquet')
    GROUP BY userid, username, DATE_TRUNC('year', CAST(entrydate AS DATE)),DATE_TRUNC('month', CAST(entrydate AS DATE))
),
u AS (
    SELECT userid,
        CONCAT(firstname, ' ', lastname) AS nombre_completo,
        departmentname AS departamento,
        currenthourlycostamount AS rate_costo
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_user_latest/data.parquet')
),
horas_mes AS (
    SELECT mes,
        ROUND(EXTRACT(DAY FROM (mes + INTERVAL '1 month' - INTERVAL '1 day'))::INT * 5.0 / 7.0 * 8, 2) AS horas_disponibles
    FROM (SELECT DISTINCT mes FROM te)
)
SELECT
   
   te.mes,
    te.userid,
    u.nombre_completo,
    te.username,
    u.departamento,
    u.rate_costo,
    hm.horas_disponibles,
    ROUND(te.horas_ejecutadas, 2)                                                     AS horas_ejecutadas,
    GREATEST(ROUND(hm.horas_disponibles - te.horas_ejecutadas, 2), 0)                AS horas_hundidas,
    ROUND(te.horas_ejecutadas * u.rate_costo, 2)                                     AS costo_ejecutado,
    ROUND(GREATEST(hm.horas_disponibles - te.horas_ejecutadas, 0) * u.rate_costo, 2) AS costo_hundido,
    ROUND(hm.horas_disponibles * u.rate_costo, 2)                                    AS costo_potencial_mes
FROM te
JOIN u  ON u.userid = te.userid
JOIN horas_mes hm ON hm.mes = te.mes
ORDER BY te.mes DESC, u.nombre_completo$seed$, $seed$Costo mensual por consultor: ejecutado (horas×rate) y hundido (horas disponibles - ejecutadas)×rate$seed$, $seed${}$seed$::jsonb, $seed$$seed$, NOW(), (SELECT id FROM workspaces ORDER BY created_at ASC LIMIT 1))
ON CONFLICT DO NOTHING;

INSERT INTO datasets (name, layer, cartridge, sources, sql_def, description, column_mapping, schedule, updated_at, workspace_id)
VALUES ($seed$pnl_detalle_consultor$seed$, $seed$gold$seed$, $seed$replicon$seed$, $seed$["silver/replicon/replicon_timeentry_latest", "silver/replicon/replicon_resourceallocation_latest", "silver/replicon/replicon_billingitem_latest", "silver/replicon/empleados_maestro", "silver/replicon/replicon_project_detail_curated", "silver/replicon/replicon_project_latest", "silver/replicon/replicon_projectbilling_curated", "silver/replicon/project_progress_history"]$seed$::jsonb, $seed$WITH

-- 1. Catalogo proyectos
proj_catalog AS (
    SELECT project_code, project_name, revenue_manager, project_type, pct_avance_real FROM (
        SELECT
            "Project Code"                                                  AS project_code,
            "Project Name"                                                  AS project_name,
            COALESCE(NULLIF(TRIM("Revenue Manager"), ''), 'N/D')            AS revenue_manager,
            "Project Type"                                                  AS project_type,
            COALESCE("% Real Progress", 0)                                  AS pct_avance_real,
            ROW_NUMBER() OVER (PARTITION BY "Project Code" ORDER BY "FechaReporte" DESC NULLS LAST) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/replicon_project_detail_curated/data.parquet')
    ) WHERE rn = 1
),

-- 2. Valor de contrato (FPP)
proj_contract AS (
    SELECT project_code, cliente, valor_contrato FROM (
        SELECT
            code                                                            AS project_code,
            clientname                                                      AS cliente,
            CASE WHEN projectcurrencyid = 8
                 THEN NULL
                 ELSE COALESCE(totalestimatedcontractamount, 0)
            END                                                             AS valor_contrato,
            ROW_NUMBER() OVER (PARTITION BY code ORDER BY load_date DESC NULLS LAST) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/replicon_project_latest/data.parquet')
    ) WHERE rn = 1
),

-- 3. Tarifa por usuario+proyecto — dedup a 1 fila por (userid, projectcode)
billing_rates AS (
    SELECT userid, projectcode, MAX(billing_rate_usd) AS billing_rate_usd
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_resourceallocation_latest/data.parquet')
    GROUP BY userid, projectcode
),

-- 4. Revenue T&M desde BillingItem (fallback) — proyecto-mes-consultor
billing_items_user AS (
    SELECT
        DATE_TRUNC('month', CAST(entrydate AS DATE))                        AS mes,
        projectcode,
        username,
        SUM(COALESCE(billableamountbasecurrency, 0))                       AS revenue_bi
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_billingitem_latest/data.parquet')
    WHERE isbillable = true AND entrydate IS NOT NULL
    GROUP BY 1, 2, 3
),

-- 5. Revenue FPP: avance_último_mes_actual − avance_último_mes_anterior × contrato
fpp_monthly_last AS (
    SELECT mes, project_code, real_progress AS last_progress
    FROM (
        SELECT
            DATE_TRUNC('month', CAST(modified_at AS DATE))                AS mes,
            project_code,
            real_progress,
            ROW_NUMBER() OVER (
                PARTITION BY project_code, DATE_TRUNC('month', CAST(modified_at AS DATE))
                ORDER BY modified_at DESC
            ) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/project_progress_history/data.parquet')
        WHERE real_progress IS NOT NULL
    ) WHERE rn = 1
),

fpp_revenue AS (
    SELECT
        m.mes, m.project_code,
        (m.last_progress - COALESCE(LAG(m.last_progress) OVER (
            PARTITION BY m.project_code ORDER BY m.mes
        ), 0)) / 100.0 * COALESCE(pc.valor_contrato, 0)                    AS revenue_usd
    FROM fpp_monthly_last m
    LEFT JOIN proj_contract pc ON pc.project_code = m.project_code
),

-- 6. Facturación por mes-proyecto (AMS Base Line / BPO)
facturacion AS (
    SELECT
        DATE_TRUNC('month', CAST("Fecha" AS DATE))                         AS mes,
        CAST(TRY_CAST(TRY_CAST("Project Code" AS DOUBLE) AS BIGINT) AS VARCHAR) AS project_code,
        CASE WHEN COUNT(*) FILTER (WHERE "Moneda" = 'MXN') > 0
             THEN NULL ELSE SUM("Subtotal") END                            AS facturacion_mes_usd
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_projectbilling_curated/data.parquet')
    WHERE "Fecha" IS NOT NULL AND "Project Code" != '0'
    GROUP BY 1, 2
),

-- 7. TimeEntry enriquecido por consultor
te_enriched AS (
    SELECT
        te.username,
        te.userid,
        te.projectcode,
        te.clientname,
        DATE_TRUNC('month', TRY_CAST(te.entrydate AS DATE))                AS mes,
        te.durationhours,
        te.isbillable,
        COALESCE(br.billing_rate_usd, 0)                                   AS billing_rate_usd,
        COALESCE(em.costo_hora, 0)                                         AS costo_hora,
        COALESCE(em.tipo_empleado, 'Unknown')                              AS tipo_empleado
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_timeentry_latest/data.parquet') te
    LEFT JOIN billing_rates br
        ON br.userid = te.userid AND br.projectcode = te.projectcode
    LEFT JOIN read_parquet('s3://{bucket}/silver/replicon/empleados_maestro/data.parquet') em
        ON LOWER(TRIM(em.usuario)) = LOWER(TRIM(te.username))
),

-- 8. Costo hundido por empleado/mes
hundido_emp AS (
    SELECT
        username, mes, costo_hora,
        SUM(CASE WHEN isbillable THEN durationhours ELSE 0 END)            AS hrs_fact_total,
        GREATEST(0, 168.0 - SUM(durationhours)) * costo_hora              AS costo_hundido_total
    FROM te_enriched
    WHERE mes IS NOT NULL AND tipo_empleado = 'Employee' AND costo_hora > 0
    GROUP BY username, mes, costo_hora
),

-- 9. Métricas TE por (mes, proyecto, consultor)
te_agg AS (
    SELECT
        mes,
        projectcode                                                         AS project_code,
        username                                                            AS consultor,
        MAX(clientname)                                                     AS cliente_te,
        MAX(billing_rate_usd)                                               AS billing_rate_usd,
        MAX(costo_hora)                                                     AS costo_hora,
        MAX(tipo_empleado)                                                  AS tipo_empleado,
        SUM(CASE WHEN isbillable     THEN durationhours ELSE 0 END)        AS horas_facturables,
        SUM(CASE WHEN NOT isbillable THEN durationhours ELSE 0 END)        AS horas_no_facturables,
        SUM(durationhours)                                                  AS horas_totales,
        SUM(CASE WHEN isbillable THEN durationhours * billing_rate_usd ELSE 0 END) AS revenue_tarifa_usr,
        SUM(CASE WHEN isbillable THEN durationhours * costo_hora ELSE 0 END) AS costo_directo
    FROM te_enriched
    WHERE mes IS NOT NULL
    GROUP BY mes, project_code, consultor
),

-- 10. Total horas facturables por (mes, proyecto) — para prorratear revenue del proyecto a consultores
proj_hrs AS (
    SELECT mes, project_code,
           SUM(horas_facturables) AS hrs_fact_proyecto
    FROM te_agg
    GROUP BY mes, project_code
)

SELECT
    ta.mes,
    COALESCE(pc.revenue_manager, 'N/D')                                    AS revenue_manager,
    COALESCE(pc2.cliente, ta.cliente_te, 'N/D')                            AS cliente,
    ta.project_code                                                         AS proyecto,
    COALESCE(pc.project_name, '')                                          AS project_name,
    COALESCE(pc.project_type, 'N/D')                                       AS tipo_proyecto,
    ta.consultor,
    ta.tipo_empleado,
    ROUND(ta.horas_facturables, 2)                                         AS horas_facturables,
    ROUND(ta.horas_no_facturables, 2)                                      AS horas_no_facturables,
    ROUND(ta.horas_totales, 2)                                             AS horas_totales,
    NULL::DOUBLE AS billing_rate_usd,
    NULL::DOUBLE AS costo_hora,
    NULL::DOUBLE AS costo_directo,
    NULL::DOUBLE AS costo_hundido_aporte,
    NULL::DOUBLE AS revenue_aporte,
    NULL::DOUBLE AS proj_revenue_fpp_mes,
    NULL::DOUBLE AS proj_facturacion_mes,
    'insufficient_data' AS financial_status
FROM te_agg ta
LEFT JOIN proj_catalog pc   ON pc.project_code  = ta.project_code
LEFT JOIN proj_contract pc2 ON pc2.project_code = ta.project_code
LEFT JOIN proj_hrs ph       ON ph.project_code  = ta.project_code AND ph.mes = ta.mes
LEFT JOIN fpp_revenue fr    ON fr.project_code  = ta.project_code AND fr.mes = ta.mes
LEFT JOIN facturacion fac   ON fac.project_code = ta.project_code AND fac.mes = ta.mes
LEFT JOIN billing_items_user biu
    ON biu.projectcode = ta.project_code AND biu.mes = ta.mes AND biu.username = ta.consultor
LEFT JOIN hundido_emp he ON he.username = ta.consultor AND he.mes = ta.mes
ORDER BY ta.mes DESC, revenue_manager, ta.project_code, ta.consultor
$seed$, $seed$P&L mensual desglosado por consultor: horas, costo directo, hundido prorrateado y revenue atribuido$seed$, $seed${}$seed$::jsonb, $seed$$seed$, NOW(), (SELECT id FROM workspaces ORDER BY created_at ASC LIMIT 1))
ON CONFLICT DO NOTHING;

INSERT INTO datasets (name, layer, cartridge, sources, sql_def, description, column_mapping, schedule, updated_at, workspace_id)
VALUES ($seed$pnl_mensual$seed$, $seed$gold$seed$, $seed$replicon$seed$, $seed$["raw/replicon/ResourceAllocation"]$seed$::jsonb, $seed$WITH

-- 1. Catalogo proyectos: tipo, revenue manager (project_detail_curated deduplicado)
proj_catalog AS (
    SELECT project_code, project_name, revenue_manager, project_type, pct_avance_real FROM (
        SELECT
            "Project Code"                                                   AS project_code,
            "Project Name"                                                   AS project_name,
            COALESCE(NULLIF(TRIM("Revenue Manager"), ''), 'N/D')            AS revenue_manager,
            "Project Type"                                                   AS project_type,
            COALESCE("% Real Progress", 0)                                   AS pct_avance_real,
            ROW_NUMBER() OVER (PARTITION BY "Project Code" ORDER BY "FechaReporte" DESC NULLS LAST) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/replicon_project_detail_curated/data.parquet')
    ) WHERE rn = 1
),

-- 2. Valor de contrato (FPP revenue base) desde project_latest
--    projectcurrencyid=1 â†’ USD, projectcurrencyid=8 â†’ MXN (Ã·20)
proj_contract AS (
    SELECT project_code, cliente, valor_contrato FROM (
        SELECT
            code                                                             AS project_code,
            clientname                                                       AS cliente,
            CASE WHEN projectcurrencyid = 8
                 THEN NULL
                 ELSE COALESCE(totalestimatedcontractamount, 0)
            END                                                              AS valor_contrato,
            ROW_NUMBER() OVER (PARTITION BY code ORDER BY load_date DESC NULLS LAST) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/replicon_project_latest/data.parquet')
    ) WHERE rn = 1
),

-- 3. Tarifas de facturacion por usuario+proyecto (T&M, AMS On Demand) — dedup a 1 fila por (userid, projectcode)
billing_rates AS (
    SELECT userid, projectcode, MAX(billing_rate_usd) AS billing_rate_usd
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_resourceallocation_latest/data.parquet')
    GROUP BY userid, projectcode
),

-- 4. Revenue T&M desde BillingItem (fallback cuando billing_rate_usd = 0)
--    billableamountbasecurrency ya viene calculado por Replicon (horas Ã— tarifa real)
billing_items AS (
    SELECT
        DATE_TRUNC('month', CAST(entrydate AS DATE))                        AS mes,
        projectcode,
        SUM(COALESCE(billableamountbasecurrency, 0))                       AS revenue_usd
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_billingitem_latest/data.parquet')
    WHERE isbillable = true AND entrydate IS NOT NULL
    GROUP BY 1, 2
),

-- 5. Revenue FPP: avance_último_mes_actual − avance_último_mes_anterior.
--    (mes anterior = el último mes con dato del proyecto, no necesariamente consecutivo).
--    Si el delta es negativo se contabiliza (revenue negativo).
fpp_monthly_last AS (
    SELECT mes, project_code, real_progress AS last_progress
    FROM (
        SELECT
            DATE_TRUNC('month', CAST(modified_at AS DATE))                AS mes,
            project_code,
            real_progress,
            ROW_NUMBER() OVER (
                PARTITION BY project_code, DATE_TRUNC('month', CAST(modified_at AS DATE))
                ORDER BY modified_at DESC
            ) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/project_progress_history/data.parquet')
        WHERE real_progress IS NOT NULL
    ) WHERE rn = 1
),

fpp_revenue AS (
    SELECT
        m.mes, m.project_code,
        (m.last_progress - COALESCE(LAG(m.last_progress) OVER (
            PARTITION BY m.project_code ORDER BY m.mes
        ), 0)) / 100.0 * COALESCE(pc.valor_contrato, 0)                    AS revenue_usd
    FROM fpp_monthly_last m
    LEFT JOIN proj_contract pc ON pc.project_code = m.project_code
),

-- 5. Facturacion en USD por proyecto/mes
--    Project Code en billing viene como float string ("29630595633.0") â€” normalizar a entero
facturacion AS (
    SELECT
        DATE_TRUNC('month', CAST("Fecha" AS DATE))                         AS mes,
        CAST(TRY_CAST(TRY_CAST("Project Code" AS DOUBLE) AS BIGINT) AS VARCHAR) AS project_code,
        CASE WHEN COUNT(*) FILTER (WHERE "Moneda" = 'MXN') > 0
             THEN NULL ELSE SUM("Subtotal") END                            AS facturacion_mes_usd
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_projectbilling_curated/data.parquet')
    WHERE "Fecha" IS NOT NULL AND "Project Code" != '0'
    GROUP BY 1, 2
),

-- 6. TimeEntry enriquecido: tarifa facturacion y costo/hora por usuario+proyecto
te_enriched AS (
    SELECT
        te.username,
        te.projectcode,
        te.clientname,
        DATE_TRUNC('month', TRY_CAST(te.entrydate AS DATE))                AS mes,
        te.durationhours,
        te.isbillable,
        COALESCE(br.billing_rate_usd, 0)                                   AS billing_rate_usd,
        COALESCE(em.costo_hora, 0)                                         AS costo_hora,
        COALESCE(em.tipo_empleado, 'Unknown')                              AS tipo_empleado
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_timeentry_latest/data.parquet') te
    LEFT JOIN billing_rates br
        ON br.userid = te.userid AND br.projectcode = te.projectcode
    LEFT JOIN read_parquet('s3://{bucket}/silver/replicon/empleados_maestro/data.parquet') em
        ON LOWER(TRIM(em.usuario)) = LOWER(TRIM(te.username))
),

-- 7a. Costo hundido por empleado/mes:
--     MAX(0, 168 - horas_totales_registradas) Ã— costo/hora
--     Ocioso puro: tiempo no registrado. costo_no_facturable no se duplica.
--     Solo Employees (no Contractors). MÃ­nimo 0.
hundido_empleado AS (
    SELECT
        username,
        mes,
        costo_hora,
        SUM(CASE WHEN isbillable THEN durationhours ELSE 0 END)            AS hrs_fact_total,
        GREATEST(0, 168.0
            - SUM(durationhours))
            * costo_hora                                                    AS costo_hundido
    FROM te_enriched
    WHERE mes IS NOT NULL AND tipo_empleado = 'Employee' AND costo_hora > 0
    GROUP BY username, mes, costo_hora
),

-- 7b. Horas facturables por empleado+proyecto+mes (pesos del prorrateo)
fact_pesos AS (
    SELECT
        username,
        mes,
        projectcode,
        SUM(durationhours)                                                  AS hrs_fact
    FROM te_enriched
    WHERE isbillable = true AND mes IS NOT NULL
    GROUP BY username, mes, projectcode
),

-- 7c. Costo hundido prorrateado a cada proyecto segÃºn peso de horas facturables
hundido_prorateado AS (
    SELECT
        fp.mes,
        fp.projectcode,
        SUM(fp.hrs_fact / NULLIF(he.hrs_fact_total, 0)
            * he.costo_hundido)                                            AS costo_hundido
    FROM fact_pesos fp
    JOIN hundido_empleado he
        ON he.username = fp.username AND he.mes = fp.mes
    GROUP BY fp.mes, fp.projectcode
),

-- 7. MÃ©tricas de tiempo por proyecto/mes (sin costo_hundido â€” viene de hundido_prorateado)
te_agg AS (
    SELECT
        mes,
        projectcode                                                         AS project_code,
        MAX(clientname)                                                     AS cliente_te,
        SUM(CASE WHEN isbillable THEN durationhours ELSE 0 END)            AS horas_facturables,
        SUM(durationhours)                                                  AS horas_totales,
        SUM(CASE WHEN isbillable
                 THEN durationhours * billing_rate_usd ELSE 0 END)         AS revenue_tarifa,
        SUM(CASE WHEN isbillable
                 THEN durationhours * costo_hora ELSE 0 END)               AS costo_directo
    FROM te_enriched
    WHERE mes IS NOT NULL
    GROUP BY mes, project_code
),

-- 8. P&L base con revenue por tipo de proyecto
pnl_base AS (
    SELECT
        ta.mes,
        COALESCE(pc.revenue_manager, 'N/D')                                AS revenue_manager,
        COALESCE(pc2.cliente, ta.cliente_te, 'N/D')                        AS cliente,
        ta.project_code                                                     AS proyecto,
        COALESCE(pc.project_name, '')                                      AS project_name,
        COALESCE(pc.project_type, 'N/D')                                   AS tipo_proyecto,
        COALESCE(pc.pct_avance_real, 0)                                    AS pct_avance_real,
        CASE
            WHEN pc.project_type = 'FPP'
                THEN COALESCE(fr.revenue_usd, 0)
            WHEN pc.project_type IN ('T&M', 'AMS (On Demand)')
                THEN CASE
                    WHEN ta.revenue_tarifa > 0 THEN ta.revenue_tarifa
                    ELSE COALESCE(bi.revenue_usd, 0)   -- fallback: BillingItem cuando tarifa no estÃ¡ en ResourceAllocation
                END
            WHEN pc.project_type IN ('AMS (Base Line)', 'BPO', 'CFDI-Timbrado')
                THEN COALESCE(fac.facturacion_mes_usd, 0)
            ELSE CASE
                    WHEN ta.revenue_tarifa > 0 THEN ta.revenue_tarifa
                    ELSE COALESCE(bi.revenue_usd, 0)
                END
        END                                                                 AS revenue_usd,
        COALESCE(fac.facturacion_mes_usd, 0)                               AS facturacion_mes_usd,
        ta.costo_directo,
        COALESCE(hp.costo_hundido, 0)                                      AS costo_hundido,
        ta.costo_directo + COALESCE(hp.costo_hundido, 0)                   AS costo_total,
        ta.horas_facturables,
        ta.horas_totales
    FROM te_agg ta
    LEFT JOIN proj_catalog pc   ON pc.project_code  = ta.project_code
    LEFT JOIN proj_contract pc2 ON pc2.project_code = ta.project_code
    LEFT JOIN fpp_revenue fr    ON fr.project_code  = ta.project_code AND fr.mes = ta.mes
    LEFT JOIN facturacion fac   ON fac.project_code = ta.project_code AND fac.mes = ta.mes
    LEFT JOIN billing_items bi  ON bi.projectcode   = ta.project_code AND bi.mes = ta.mes
    LEFT JOIN hundido_prorateado hp ON hp.projectcode = ta.project_code AND hp.mes = ta.mes
)

SELECT
    mes,
    revenue_manager,
    cliente,
    proyecto,
    project_name,
    tipo_proyecto,
    NULL::DOUBLE AS revenue_usd,
    NULL::DOUBLE AS facturacion_mes_usd,
    NULL::DOUBLE AS wip_usd,
    NULL::DOUBLE AS costo_directo,
    NULL::DOUBLE AS costo_hundido,
    NULL::DOUBLE AS costo_total,
    NULL::DOUBLE AS margen_bruto_usd,
    NULL::DOUBLE AS margen_bruto_pct,
    ROUND(horas_facturables, 2)                                            AS horas_facturables,
    ROUND(horas_totales, 2)                                                AS horas_totales,
    ROUND(pct_avance_real, 2)                                              AS pct_avance_real,
    'insufficient_data' AS financial_status
FROM pnl_base
ORDER BY mes DESC, revenue_manager, cliente, proyecto$seed$, $seed$P&L mensual por Revenue Manager/Cliente/Proyecto. Revenue por tipo: FPP=avance*contrato, T&M/AMS On Demand=horas*tarifa, AMS Base Line/BPO=facturado. Costo en directo+hundido. WIP=revenue-facturacion.$seed$, $seed${}$seed$::jsonb, $seed$$seed$, NOW(), (SELECT id FROM workspaces ORDER BY created_at ASC LIMIT 1))
ON CONFLICT DO NOTHING;

INSERT INTO datasets (name, layer, cartridge, sources, sql_def, description, column_mapping, schedule, updated_at, workspace_id)
VALUES ($seed$replicon_fte_profitability_monthly$seed$, $seed$gold$seed$, $seed$replicon$seed$, $seed$[]$seed$::jsonb, $seed$WITH

-- 1. Catálogo de empleados
empleados AS (
    SELECT
        LOWER(TRIM(usuario))                                    AS usuario_key,
        TRIM(usuario)                                           AS consultor,
        COALESCE(NULLIF(TRIM(supervisor_nombre), ''), 'N/D')   AS supervisor,
        COALESCE(NULLIF(TRIM(departamento), ''), 'N/D')        AS departamento,
        COALESCE(tipo_empleado, 'Unknown')                     AS tipo_empleado,
        COALESCE(costo_hora, 0)                                AS costo_hora
    FROM read_parquet('s3://{bucket}/silver/replicon/empleados_maestro/data.parquet')
),

-- 2. Tarifa de facturación
billing_rates AS (
    SELECT userid, projectcode, billing_rate_usd
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_resourceallocation_latest/data.parquet')
),

-- 3. Revenue manager por proyecto
proj_rm AS (
    SELECT project_code, project_name, revenue_manager FROM (
        SELECT
            "Project Code"                                      AS project_code,
            "Project Name"                                      AS project_name,
            COALESCE(NULLIF(TRIM("Revenue Manager"), ''), 'N/D') AS revenue_manager,
            ROW_NUMBER() OVER (
                PARTITION BY "Project Code"
                ORDER BY "FechaReporte" DESC NULLS LAST
            ) AS rn
        FROM read_parquet('s3://{bucket}/silver/replicon/replicon_project_detail_curated/data.parquet')
    ) WHERE rn = 1
),

-- 4. BillingItem
billing_items AS (
    SELECT
        DATE_TRUNC('month', TRY_CAST(entrydate AS DATE))       AS mes,
        username,
        projectcode,
        SUM(COALESCE(billableamountbasecurrency, 0))           AS revenue_bi
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_billingitem_latest/data.parquet')
    WHERE isbillable = true AND entrydate IS NOT NULL
    GROUP BY 1, 2, 3
),

-- 5. TimeEntry enriquecido
te AS (
    SELECT
        DATE_TRUNC('month', TRY_CAST(te.entrydate AS DATE))    AS mes,
        te.username,
        te.userid,
        te.projectcode,
        te.clientname,
        te.durationhours,
        te.isbillable,
        COALESCE(br.billing_rate_usd, 0)                       AS billing_rate_usd,
        COALESCE(em.costo_hora, 0)                             AS costo_hora,
        COALESCE(em.supervisor, 'N/D')                         AS supervisor,
        COALESCE(em.departamento, 'N/D')                       AS departamento,
        COALESCE(em.tipo_empleado, 'Unknown')                  AS tipo_empleado,
        COALESCE(em.consultor, te.username)                    AS consultor_nombre
    FROM read_parquet('s3://{bucket}/silver/replicon/replicon_timeentry_latest/data.parquet') te
    LEFT JOIN billing_rates br
        ON br.userid = te.userid AND br.projectcode = te.projectcode
    LEFT JOIN empleados em
        ON em.usuario_key = LOWER(TRIM(te.username))
),

-- 6. Costo hundido a nivel empleado/mes
hundido_emp AS (
    SELECT
        username, mes, costo_hora,
        SUM(CASE WHEN isbillable THEN durationhours ELSE 0 END) AS hrs_fact_total,
        SUM(durationhours)                                      AS hrs_total,
        GREATEST(0, 168.0 - SUM(durationhours)) * costo_hora   AS costo_hundido
    FROM te
    WHERE mes IS NOT NULL
      AND tipo_empleado = 'Employee'
      AND costo_hora > 0
    GROUP BY username, mes, costo_hora
),

-- 7. Peso de horas facturables
fact_pesos AS (
    SELECT
        username, mes, projectcode,
        SUM(CASE WHEN isbillable THEN durationhours ELSE 0 END) AS hrs_fact
    FROM te
    WHERE mes IS NOT NULL
    GROUP BY username, mes, projectcode
),

-- 8. Costo hundido prorrateado
hundido_proj AS (
    SELECT
        fp.mes, fp.username, fp.projectcode,
        SUM(fp.hrs_fact / NULLIF(he.hrs_fact_total, 0) * he.costo_hundido) AS costo_hundido
    FROM fact_pesos fp
    JOIN hundido_emp he
        ON he.username = fp.username AND he.mes = fp.mes
    GROUP BY fp.mes, fp.username, fp.projectcode
),

-- 9. Agregación principal
te_agg AS (
    SELECT
        mes,
        username,
        MAX(consultor_nombre)                                  AS consultor,
        MAX(supervisor)                                        AS supervisor,
        MAX(departamento)                                      AS departamento,
        MAX(tipo_empleado)                                     AS tipo_empleado,
        projectcode,
        MAX(clientname)                                        AS cliente,
        MAX(billing_rate_usd)                                  AS billing_rate_usd,
        MAX(costo_hora)                                        AS costo_hora,
        SUM(durationhours)                                     AS horas_ejecutadas,
        SUM(CASE WHEN isbillable  THEN durationhours ELSE 0 END) AS horas_facturables,
        SUM(CASE WHEN NOT isbillable THEN durationhours ELSE 0 END) AS horas_no_facturables,
        SUM(CASE WHEN isbillable  THEN durationhours * billing_rate_usd ELSE 0 END) AS revenue_tarifa,
        SUM(CASE WHEN isbillable  THEN durationhours * costo_hora ELSE 0 END) AS costo_directo,
        SUM(CASE WHEN NOT isbillable THEN durationhours * costo_hora ELSE 0 END) AS costo_no_facturable
    FROM te
    WHERE mes IS NOT NULL
    GROUP BY mes, username, projectcode
)

SELECT
    ta.mes,
    COALESCE(NULLIF(ta.supervisor,'N/D'), pr.revenue_manager, 'N/D') AS revenue_manager,
    ta.departamento,
    ta.consultor,
    ta.tipo_empleado,
    ta.projectcode                                             AS proyecto,
    COALESCE(pr.project_name, '')                              AS project_name,
    ta.cliente,
    ROUND(ta.horas_ejecutadas, 2)                              AS horas_ejecutadas,
    ROUND(ta.horas_facturables, 2)                             AS horas_facturables,
    ROUND(ta.horas_no_facturables, 2)                          AS horas_no_facturables,
    ROUND(GREATEST(0, 168.0 - ta.horas_ejecutadas), 2)        AS horas_hundidas_capacidad,
    ta.billing_rate_usd,
    ta.costo_hora,
    ROUND(ta.costo_directo, 2)                                 AS costo_directo,
    ROUND(ta.costo_no_facturable, 2)                           AS costo_no_facturable,
    ROUND(COALESCE(hp.costo_hundido, 0), 2)                   AS costo_hundido,
    ROUND(ta.costo_directo + ta.costo_no_facturable + COALESCE(hp.costo_hundido, 0), 2) AS costo_total,
    ROUND(CASE WHEN ta.revenue_tarifa > 0 THEN ta.revenue_tarifa ELSE COALESCE(bi.revenue_bi, 0) END, 2) AS revenue_generado
FROM te_agg ta
LEFT JOIN hundido_proj hp
    ON hp.username = ta.username AND hp.projectcode = ta.projectcode AND hp.mes = ta.mes
LEFT JOIN proj_rm pr
    ON pr.project_code = ta.projectcode
LEFT JOIN billing_items bi
    ON bi.username = ta.username AND bi.projectcode = ta.projectcode AND bi.mes = ta.mes$seed$, $seed$Análisis de productividad mes a mes$seed$, $seed${}$seed$::jsonb, $seed$$seed$, NOW(), (SELECT id FROM workspaces ORDER BY created_at ASC LIMIT 1))
ON CONFLICT DO NOTHING;

INSERT INTO datasets (name, layer, cartridge, sources, sql_def, description, column_mapping, schedule, updated_at, workspace_id)
VALUES ($seed$empleados_maestro$seed$, $seed$gold$seed$, $seed$replicon$seed$, $seed$["raw/replicon/User"]$seed$::jsonb, $seed$SELECT 
  userid AS id_empleado,
  firstname AS nombre,
  lastname AS apellido,
  username AS usuario,
  email,
  departmentname AS departamento,
  locationname AS ubicacion,
  employeetypename AS tipo_empleado,
  CAST(currenthourlycostamount AS DECIMAL(10,2)) AS costo_hora,
  CAST(currenthourlybillingamount AS DECIMAL(10,2)) AS tarifa_facturacion,
  CAST(startdate AS DATE) AS fecha_inicio,
  CAST(enddate AS DATE) AS fecha_fin,
  currentsupervisoruserid AS supervisor_id,
  currentsupervisorusername AS supervisor,
  isenabled AS activo,
  load_date AS fecha_carga
FROM read_parquet('s3://modecissions-lakehouse-0baf85/silver/replicon/replicon_user_latest/**/*.parquet')
WHERE isenabled = true
ORDER BY id_empleado$seed$, $seed$Maestro de empleados activos de Replicon con datos de costo, departamento, ubicación, supervisor y fechas de inicio/fin. Derivado de replicon_user_latest (Silver) filtrado a isenabled=true.$seed$, $seed${}$seed$::jsonb, $seed$$seed$, NOW(), (SELECT id FROM workspaces ORDER BY created_at ASC LIMIT 1))
ON CONFLICT DO NOTHING;

INSERT INTO datasets (name, layer, cartridge, sources, sql_def, description, column_mapping, schedule, updated_at, workspace_id)
VALUES ($seed$project_progress_history$seed$, $seed$silver$seed$, $seed$replicon$seed$, $seed$["raw/replicon/ProjectAudit"]$seed$::jsonb, $seed$WITH src AS (
  SELECT DISTINCT
    "Project Code"    AS project_code,
    "Project Name"    AS project_name,
    "Project Manager" AS project_manager,
    "Field"           AS field,
    "Original Value"  AS prev_value,
    "New Value"       AS new_value,
    ROUND("New Value" - COALESCE("Original Value", 0), 4) AS increment,
    "Modified By"     AS modified_by,
    TRY_STRPTIME("Modified On", '%d/%m/%Y %I:%M:%S %p') AS modified_at
  FROM read_parquet('s3://{bucket}/raw/replicon/ProjectAudit/load_date=*/data.parquet',
    hive_partitioning=true, union_by_name=true)
  WHERE "Field" IN ('% Plan Progress', '% Real Progress')
    AND "New Value" IS NOT NULL
)
SELECT
  project_code,
  project_name,
  project_manager,
  modified_at,
  modified_by,
  MAX(CASE WHEN field = '% Plan Progress' THEN prev_value END)  AS plan_progress_prev,
  MAX(CASE WHEN field = '% Plan Progress' THEN new_value END)   AS plan_progress,
  MAX(CASE WHEN field = '% Plan Progress' THEN increment END)   AS plan_progress_increment,
  MAX(CASE WHEN field = '% Real Progress' THEN prev_value END)  AS real_progress_prev,
  MAX(CASE WHEN field = '% Real Progress' THEN new_value END)   AS real_progress,
  MAX(CASE WHEN field = '% Real Progress' THEN increment END)   AS real_progress_increment
FROM src
GROUP BY project_code, project_name, project_manager, modified_at, modified_by
ORDER BY project_code, modified_at$seed$, $seed$Historial de cambios en % Plan Progress y % Real Progress por proyecto. Una fila por evento de cambio con incremento respecto al valor anterior.$seed$, $seed${}$seed$::jsonb, $seed$$seed$, NOW(), (SELECT id FROM workspaces ORDER BY created_at ASC LIMIT 1))
ON CONFLICT DO NOTHING;

