-- ── Analytic Apps ───────────────────────────────────────────
INSERT INTO analytic_apps (name, title, html, description, cartridge_id, visibility, datasets_used, updated_at)
VALUES ($seed$consultor_horas_costos$seed$, $seed$Consultores — Horas y Costos$seed$, $seed$<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Consultores — Horas y Costos</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
:root{
  --bg:#0d1117;--bg2:#161b22;--bg3:#1e2736;--border:#30363d;
  --text1:#e6edf3;--text2:#8b949e;--text3:#58626d;
  --green:#2ea043;--blue:#7c9fff;--amber:#e3b341;--red:#f85149;--purple:#bc8cff;
  --card-r:8px;
}
[data-theme=light]{
  --bg:#f0f2f5;--bg2:#ffffff;--bg3:#e8ecf1;--border:#d0d7de;
  --text1:#1f2328;--text2:#656d76;--text3:#a0aab4;
  --green:#1a7f37;--blue:#0969da;--amber:#9a6700;--red:#cf222e;--purple:#8250df;
}
*{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--text1);font-family:system-ui,-apple-system,sans-serif;min-height:100vh;transition:background .2s,color .2s}

.hdr{background:var(--bg2);border-bottom:1px solid var(--border);padding:16px 28px;display:flex;align-items:center;gap:12px}
.hdr-title{font-size:13px;font-weight:700;letter-spacing:1px;color:var(--purple);flex:1}
.hdr-sub{font-size:10px;color:var(--text2);letter-spacing:1px}
.theme-btn{background:transparent;border:1px solid var(--border);color:var(--text2);padding:5px 12px;font-size:10px;border-radius:20px;cursor:pointer}
.theme-btn:hover{border-color:var(--purple);color:var(--purple)}

.filters{background:var(--bg2);border-bottom:1px solid var(--border);padding:12px 28px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.filter-group{display:flex;align-items:center;gap:6px}
label{font-size:10px;color:var(--text2);white-space:nowrap;font-weight:600;letter-spacing:.5px}
.btn{padding:8px 20px;font-size:11px;font-weight:600;border-radius:6px;cursor:pointer;border:none;letter-spacing:.5px}
.btn-primary{background:var(--purple);color:#fff}
.btn-primary:hover{opacity:.9}
.btn-primary:disabled{opacity:.4;cursor:not-allowed}
.spinner{display:inline-block;width:10px;height:10px;border:2px solid rgba(255,255,255,.3);border-top-color:#fff;border-radius:50%;animation:spin .6s linear infinite;vertical-align:middle;margin-right:6px}
@keyframes spin{to{transform:rotate(360deg)}}

/* Multi-select */
.ms-wrap{position:relative;min-width:160px}
.ms-trigger{background:var(--bg);border:1px solid var(--border);color:var(--text1);padding:7px 28px 7px 12px;font-size:11px;border-radius:6px;cursor:pointer;width:100%;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;position:relative}
.ms-trigger::after{content:'▾';position:absolute;right:9px;top:50%;transform:translateY(-50%);color:var(--text2);font-size:10px;pointer-events:none}
.ms-trigger.open,.ms-trigger:focus{outline:none;border-color:var(--purple)}
.ms-dropdown{position:absolute;top:calc(100% + 3px);left:0;min-width:100%;background:var(--bg2);border:1px solid var(--purple);border-radius:6px;z-index:999;max-height:220px;overflow-y:auto;box-shadow:0 8px 24px rgba(0,0,0,.5);display:none}
.ms-dropdown.open{display:block}
.ms-search{width:100%;background:var(--bg);border:none;border-bottom:1px solid var(--border);color:var(--text1);padding:7px 10px;font-size:10px;outline:none}
.ms-opt{display:flex;align-items:center;gap:7px;padding:6px 10px;cursor:pointer;font-size:10px}
.ms-opt:hover{background:var(--bg3)}
.ms-opt input[type=checkbox]{accent-color:var(--purple);width:11px;height:11px;flex-shrink:0}
.ms-actions{display:flex;gap:4px;padding:5px 8px;border-top:1px solid var(--border)}
.ms-act{flex:1;background:transparent;border:1px solid var(--border);color:var(--text2);padding:3px;font-size:9px;border-radius:3px;cursor:pointer}
.ms-act:hover{border-color:var(--purple);color:var(--purple)}

.content{padding:24px 28px;max-width:1600px;margin:0 auto}
.placeholder{text-align:center;padding:100px 20px;color:var(--text2)}
.placeholder-icon{font-size:40px;margin-bottom:16px;opacity:.3}
.placeholder h2{font-size:14px;font-weight:400;margin-bottom:8px}
.placeholder p{font-size:11px;color:var(--text3)}

/* KPI strip */
.kpi-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(155px,1fr));gap:12px;margin-bottom:24px}
.kpi-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r);padding:16px 18px;border-left:3px solid var(--accent,var(--border))}
.kpi-label{font-size:9px;color:var(--text2);letter-spacing:1.5px;font-weight:600;margin-bottom:7px;text-transform:uppercase}
.kpi-val{font-size:20px;font-weight:700;line-height:1}
.kpi-sub{font-size:9px;color:var(--text3);margin-top:4px}

/* Section */
.section{margin-bottom:28px}
.section-hdr{display:flex;align-items:baseline;gap:10px;margin-bottom:12px;border-bottom:1px solid var(--border);padding-bottom:8px}
.section-title{font-size:10px;font-weight:700;letter-spacing:1.5px;color:var(--text2);text-transform:uppercase}
.section-count{font-size:10px;color:var(--text3)}

/* Chart */
.chart-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r);padding:20px;margin-bottom:24px}
canvas{max-height:260px}

/* Table */
.tbl-wrap{overflow-x:auto;background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r)}
.tbl-wrap table{border-collapse:collapse}
table{width:100%;border-collapse:collapse;font-size:10px}
th{padding:9px 12px;text-align:right;color:var(--text2);font-size:9px;letter-spacing:.8px;border-bottom:1px solid var(--border);white-space:nowrap;font-weight:600;cursor:pointer;user-select:none}
th:hover{color:var(--purple)}
th.left{text-align:left}
th.active{color:var(--purple)}
td{padding:8px 12px;text-align:right;border-bottom:1px solid var(--bg3);white-space:nowrap;font-size:10px}
td.left{text-align:left;color:var(--text2)}
td.name{text-align:left;color:var(--text1);font-weight:500}
tr:hover td{background:var(--bg3)}
tr.subtotal td{background:var(--bg3);font-weight:600;font-size:9px;color:var(--text2)}
tr.grand-total td{border-top:2px solid var(--purple);font-weight:700;color:var(--purple)}
.bar-cell{width:80px}
.mini-bar{height:5px;background:var(--bg3);border-radius:3px;overflow:hidden;margin-top:3px}
.mini-fill{height:100%;border-radius:3px}
.pos{color:var(--green)}.neg{color:var(--red)}.neu{color:var(--blue)}.warn{color:var(--amber)}
.badge{display:inline-block;padding:2px 7px;border-radius:10px;font-size:8px;font-weight:700;letter-spacing:.5px}
.badge-emp{background:rgba(124,159,255,.15);color:var(--blue)}
.badge-con{background:rgba(188,140,255,.15);color:var(--purple)}
.sort-icon{font-size:8px;margin-left:3px;opacity:.4}
.sort-icon.on{opacity:1}
</style>
</head>
<body>

<div class="hdr">
  <div>
    <div class="hdr-title">◇ CONSULTORES — HORAS Y COSTOS</div>
    <div class="hdr-sub">Gold table consultor_mensual · Año fiscal mar–feb</div>
  </div>
  <button class="theme-btn" id="theme-btn" onclick="toggleTheme()">☀ Claro</button>
</div>

<div class="filters">
  <div class="filter-group"><label>Revenue Manager</label><div class="ms-wrap" id="ms-rm"></div></div>
  <div class="filter-group"><label>Año Fiscal</label><div class="ms-wrap" id="ms-yr"></div></div>
  <div class="filter-group"><label>Proyecto</label><div class="ms-wrap" id="ms-pr" style="min-width:200px"></div></div>
  <div class="filter-group"><label>Consultor</label><div class="ms-wrap" id="ms-con" style="min-width:180px"></div></div>
  <div class="filter-group"><label>Tipo Empleado</label><div class="ms-wrap" id="ms-tipo"></div></div>
  <div class="filter-group">
    <label>Utilización del mes (vs 168h)</label>
    <div style="display:flex;gap:4px;align-items:center;flex-wrap:wrap">
      <select id="util-mes" style="background:var(--bg2);color:var(--text);border:1px solid var(--border);padding:4px 6px;font-size:11px;border-radius:2px;min-width:90px">
        <option value="">— mes —</option>
      </select>
      <select id="util-op" style="background:var(--bg2);color:var(--text);border:1px solid var(--border);padding:4px 6px;font-size:11px;border-radius:2px">
        <option value="">—</option>
        <option value="lt">&lt;</option>
        <option value="lte">≤</option>
        <option value="gt">&gt;</option>
        <option value="gte">≥</option>
      </select>
      <input id="util-val" type="number" min="0" max="200" step="1" placeholder="%" style="width:55px;background:var(--bg2);color:var(--text);border:1px solid var(--border);padding:4px 6px;font-size:11px;border-radius:2px">
      <span id="mes-actual-tag" style="font-size:9px;color:var(--text3);letter-spacing:.5px;margin-left:4px"></span>
    </div>
  </div>
  <button class="btn btn-primary" id="btn-filter" onclick="applyFilter()">Ver resultados</button>
</div>

<div class="content">
  <div id="placeholder" class="placeholder">
    <div class="placeholder-icon">👥</div>
    <h2>Selecciona filtros y presiona <strong style="color:var(--purple)">Ver resultados</strong></h2>
    <p>Horas ejecutadas · Facturables · No facturables · Costo hundido</p>
  </div>
  <div id="main" style="display:none">
    <div class="kpi-strip" id="kpis"></div>
    <div class="section">
      <div class="section-hdr"><span class="section-title">Tendencia de horas</span></div>
      <div class="chart-card"><canvas id="chart"></canvas></div>
    </div>
    <div class="section">
      <div class="section-hdr">
        <span class="section-title">Matriz de asignación mensual</span>
        <span class="section-count">Horas asignadas · % vs 168h</span>
      </div>
      <div class="tbl-wrap" id="matrix-wrap"></div>
    </div>
    <div class="section">
      <div class="section-hdr">
        <span class="section-title">Desglose por consultor y proyecto</span>
        <span class="section-count" id="tbl-count"></span>
      </div>
      <div class="tbl-wrap" id="tbl-wrap"></div>
    </div>
  </div>
</div>

<script>
let ROWS=[], ASIG=[], chartInst=null;
const PROJ_LABEL={};

const fmt  = n => n==null?'—':'$'+Number(n).toLocaleString('es-MX',{minimumFractionDigits:0,maximumFractionDigits:0});
const fmtH = n => n==null?'—':Number(n).toLocaleString('es-MX',{minimumFractionDigits:1,maximumFractionDigits:1})+'h';
const fmtP = n => n==null?'—':Number(n).toFixed(1)+'%';
const fmtR = n => n==null?'—':'$'+Number(n).toFixed(2)+'/h';

function fiscalYear(s){const p=(s||'').slice(0,7).split('-');const yr=parseInt(p[0])||0,mo=parseInt(p[1])||0;return mo<=2?yr-1:yr;}
function groupBy(arr,key){return arr.reduce((m,r)=>{(m[r[key]]=m[r[key]]||[]).push(r);return m;},{});}
function sum(rows,key){return rows.reduce((a,r)=>a+(+r[key]||0),0);}
function sumRow(rows){
  const k=['horas_asignadas','horas_ejecutadas','horas_facturables','horas_no_facturables','costo_directo','costo_no_facturable','costo_hundido','costo_total','revenue_generado'];
  const a={}; k.forEach(f=>a[f]=sum(rows,f));
  a.margen_usd=a.revenue_generado-a.costo_total;
  a.util_pct=a.horas_ejecutadas?a.horas_facturables/a.horas_ejecutadas*100:null;
  a.ejec_vs_asig_pct=a.horas_asignadas?a.horas_ejecutadas/a.horas_asignadas*100:null;
  return a;
}

// ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
const MS={};
function msCreate(id,ph='Todos'){
  const w=document.getElementById(id);
  w.innerHTML=`<button class="ms-trigger">${ph}</button>
    <div class="ms-dropdown" id="${id}-dd">
      <input class="ms-search" placeholder="Buscar…" oninput="msRender('${id}',this.value)">
      <div id="${id}-list"></div>
      <div class="ms-actions">
        <button class="ms-act" onclick="msAll('${id}',true)">TODO</button>
        <button class="ms-act" onclick="msAll('${id}',false)">NINGUNO</button>
      </div>
    </div>`;
  MS[id]={selected:new Set(),options:[],ph,labelFn:null};
  w.querySelector('.ms-trigger').addEventListener('click',function(e){
    e.stopPropagation();
    msToggle(id);
  });
  document.addEventListener('click',function(e){if(!w.contains(e.target))msClose(id);});
}
function msToggle(id){
  const dd=document.getElementById(id+'-dd'),btn=document.querySelector('#'+id+' .ms-trigger');
  const was=dd.classList.contains('open');
  Object.keys(MS).forEach(k=>msClose(k));
  if(!was){dd.classList.add('open');btn.classList.add('open');}
}
function msClose(id){document.getElementById(id+'-dd')?.classList.remove('open');document.querySelector(`#${id} .ms-trigger`)?.classList.remove('open');}
function msSetOptions(id,opts,labelFn=null){MS[id].options=opts;MS[id].labelFn=labelFn;msRender(id,'');}
function msRender(id,search){
  const {options,selected,labelFn}=MS[id];
  const fil=search?options.filter(o=>String(labelFn?labelFn(o):o).toLowerCase().includes(search.toLowerCase())):options;
  document.getElementById(id+'-list').innerHTML=fil.map(o=>{
    const lbl=labelFn?labelFn(o):o, val=String(o);
    return `<label class="ms-opt"><input type="checkbox" value="${val}" ${selected.has(val)?'checked':''} onchange="msCheck('${id}','${val.replace(/'/g,"\\'")}',this.checked)"><span>${lbl}</span></label>`;
  }).join('');
}
function msCheck(id,val,chk){chk?MS[id].selected.add(val):MS[id].selected.delete(val);msLabel(id);msCascade(id);}
function msAll(id,sel){sel?MS[id].options.forEach(o=>MS[id].selected.add(String(o))):MS[id].selected.clear();msRender(id,'');msLabel(id);msCascade(id);}
function msCascade(id){
  if(id==='ms-rm'||id==='ms-yr'){clearTimeout(MS._t);MS._t=setTimeout(refreshProyectos,400);}
  if(id==='ms-pr'){clearTimeout(MS._t2);MS._t2=setTimeout(refreshConsultores,400);}
}
function msLabel(id){
  const {selected,ph,labelFn}=MS[id];
  const btn=document.querySelector(`#${id} .ms-trigger`);
  if(!selected.size)btn.textContent=ph;
  else if(selected.size===1)btn.textContent=labelFn?labelFn([...selected][0]):[...selected][0];
  else btn.textContent=`${selected.size} seleccionados`;
}
function msGet(id){return[...MS[id].selected];}

// ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
async function loadInitialOptions(){
  msCreate('ms-rm','Todos');
  msCreate('ms-yr','Selecciona...');
  msCreate('ms-pr','Todos');
  msCreate('ms-con','Todos');
  msCreate('ms-tipo','Todos');

  try{
    const r=await fetch('/api/data/consultor_mensual/options?columns=revenue_manager,tipo_empleado');
    const o=await r.json();
    msSetOptions('ms-rm',o.revenue_manager||[]);
    msSetOptions('ms-tipo',o.tipo_empleado||[]);
  }catch(e){}

  try{
    const r=await fetch('/api/data/consultor_mensual/query',{method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters:{},limit:5000,columns:['mes']})});
    const rows=await r.json();
    if(Array.isArray(rows)){
      const fys=[...new Set(rows.map(r=>fiscalYear(r.mes)).filter(Boolean))].sort().reverse();
      msSetOptions('ms-yr',fys,y=>`AF${y} (mar ${y} – feb ${y+1})`);
    }
  }catch(e){}

  await refreshProyectos();
}

async function refreshProyectos(){
  const rm=msGet('ms-rm'),yr=msGet('ms-yr').map(Number);
  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  try{
    const r=await fetch('/api/data/consultor_mensual/query',{method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:10000,columns:['proyecto','project_name']})});
    const rows=await r.json();
    if(!Array.isArray(rows)) return;
    rows.forEach(r=>{
      if(r.proyecto&&!PROJ_LABEL[r.proyecto])
        PROJ_LABEL[r.proyecto]=r.project_name?`${r.proyecto} — ${r.project_name}`:r.proyecto;
    });
    const prevPr=msGet('ms-pr');
    const prs=[...new Set(rows.map(r=>r.proyecto).filter(Boolean))].sort();
    msSetOptions('ms-pr',prs,p=>PROJ_LABEL[p]||p);
    prevPr.forEach(v=>{if(prs.includes(v))MS['ms-pr'].selected.add(v);}); msLabel('ms-pr');
  }catch(e){}
  await refreshConsultores();
}

async function refreshConsultores(){
  const rm=msGet('ms-rm'),yr=msGet('ms-yr').map(Number),pr=msGet('ms-pr');
  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  if(pr.length) filters.proyecto=pr.length===1?pr[0]:pr;
  try{
    const r=await fetch('/api/data/consultor_mensual/query',{method:'POST',
      headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:10000,columns:['consultor']})});
    const rows=await r.json();
    if(!Array.isArray(rows)) return;
    const prevCon=msGet('ms-con');
    const cons=[...new Set(rows.map(r=>r.consultor).filter(Boolean))].sort();
    msSetOptions('ms-con',cons);
    prevCon.forEach(v=>{if(cons.includes(v))MS['ms-con'].selected.add(v);}); msLabel('ms-con');
  }catch(e){}
}

// ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
async function applyFilter(){
  const rm=msGet('ms-rm'),yr=msGet('ms-yr').map(Number),con=msGet('ms-con'),pr=msGet('ms-pr'),tp=msGet('ms-tipo');
  const filters={};
  if(rm.length)  filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length)  filters.fiscal_year=yr.length===1?yr[0]:yr;
  if(pr.length)  filters.proyecto=pr.length===1?pr[0]:pr;
  if(con.length) filters.consultor=con.length===1?con[0]:con;
  if(tp.length)  filters.tipo_empleado=tp.length===1?tp[0]:tp;

  const btn=document.getElementById('btn-filter');
  btn.innerHTML='<span class="spinner"></span>Cargando…';btn.disabled=true;
  try{
    const [r1, r2] = await Promise.all([
      fetch('/api/data/consultor_mensual/query',{method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({filters,limit:10000})}),
      fetch('/api/data/consultor_asignacion/query',{method:'POST',
        headers:{'Content-Type':'application/json'},
        body:JSON.stringify({filters,limit:20000})}),
    ]);
    ROWS = await r1.json(); if(!Array.isArray(ROWS)) ROWS=[];
    ASIG = await r2.json(); if(!Array.isArray(ASIG)) ASIG=[];
    [...ROWS,...ASIG].forEach(r=>{
      if(r.proyecto&&!PROJ_LABEL[r.proyecto])
        PROJ_LABEL[r.proyecto]=r.project_name?`${r.proyecto} — ${r.project_name}`:r.proyecto;
    });

    // Poblar dropdown de meses con los disponibles en el resultado
    const mesesDisponibles = [...new Set(ROWS.map(r=>String(r.mes).slice(0,7)).filter(Boolean))].sort();
    const utilMesSel = document.getElementById('util-mes');
    const prevMes = utilMesSel.value;
    utilMesSel.innerHTML = '<option value="">— mes —</option>' +
      mesesDisponibles.map(m=>{
        const p=m.split('-'); const lbl=`${['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'][+p[1]]} ${p[0].slice(2)}`;
        return `<option value="${m}" ${m===prevMes?'selected':''}>${lbl}</option>`;
      }).join('');

    // Filtro de utilización del mes seleccionado (post-fetch)
    //   pasado     → util = horas_facturables / 168
    //   actual/fut → util = horas_asignadas   / 168
    const utilOp = document.getElementById('util-op').value;
    const utilVal = parseFloat(document.getElementById('util-val').value);
    const utilMes = utilMesSel.value;  // formato 'YYYY-MM'
    const today = new Date();
    const curMes = `${today.getFullYear()}-${String(today.getMonth()+1).padStart(2,'0')}`;
    if(utilOp && !isNaN(utilVal) && utilMes){
      const isPast = utilMes < curMes;
      const cmp = (a,b) => utilOp==='lt'?a<b: utilOp==='lte'?a<=b: utilOp==='gt'?a>b: utilOp==='gte'?a>=b: false;
      const byC = {};   // consultor → {fact, asig} en utilMes
      ROWS.forEach(r=>{
        if(String(r.mes).slice(0,7) !== utilMes) return;
        const k = r.consultor;
        if(!byC[k]) byC[k]={fact:0, asig:0};
        byC[k].fact += +r.horas_facturables||0;
        byC[k].asig += +r.horas_asignadas ||0;
      });
      const matchingCons = new Set();
      Object.entries(byC).forEach(([c,v])=>{
        const numer = isPast ? v.fact : v.asig;
        const u = numer / 168 * 100;
        if(cmp(u, utilVal)) matchingCons.add(c);
      });
      ROWS = ROWS.filter(r=>matchingCons.has(r.consultor));
      ASIG = ASIG.filter(r=>matchingCons.has(r.consultor));
    }

    document.getElementById('placeholder').style.display='none';
    document.getElementById('main').style.display='';
    render();
  }catch(e){alert('Error: '+e.message);}
  finally{btn.textContent='Ver resultados';btn.disabled=false;}
}

// ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
function render(){renderKPIs(ROWS);renderChart(ROWS);renderMatrix(ASIG);renderTable(ROWS);}

function renderKPIs(rows){
  const t=sumRow(rows);
  const nCon=new Set(rows.map(r=>r.consultor)).size;
  const nProj=new Set(rows.map(r=>r.proyecto)).size;
  const items=[
    {label:'Consultores',         val:nCon,              sub:nProj+' proyectos',            accent:'var(--purple)'},
    {label:'Horas Asignadas',     val:fmtH(t.horas_asignadas),    sub:'según ResourceAllocation', accent:'var(--purple)'},
    {label:'Horas Ejecutadas',    val:fmtH(t.horas_ejecutadas),   sub:fmtP(t.ejec_vs_asig_pct)+' vs asignadas', accent:'var(--blue)'},
    {label:'Horas Facturables',   val:fmtH(t.horas_facturables),  sub:fmtP(t.util_pct)+' utilización', accent:'var(--green)'},
    {label:'Horas No Facturables',val:fmtH(t.horas_no_facturables),sub:'no billable',      accent:'var(--amber)'},
    {label:'Costo Directo',       val:fmt(t.costo_directo),        sub:'hrs fact × costo/h',accent:'var(--blue)'},
    {label:'Costo No Facturable', val:fmt(t.costo_no_facturable),  sub:'hrs no-fact × costo/h',accent:'var(--amber)'},
    {label:'Costo Hundido',       val:fmt(t.costo_hundido),        sub:'capacidad ociosa (168h)',accent:'var(--red)'},
    {label:'Revenue Generado',    val:fmt(t.revenue_generado),     sub:'facturables × tarifa',accent:'var(--green)'},
  ];
  document.getElementById('kpis').innerHTML=items.map(({label,val,sub,accent})=>`
    <div class="kpi-card" style="--accent:${accent}">
      <div class="kpi-label">${label}</div>
      <div class="kpi-val">${val}</div>
      <div class="kpi-sub">${sub}</div>
    </div>`).join('');
}

function renderChart(rows){
  const byMes=groupBy(rows,'mes');
  const meses=Object.keys(byMes).sort();
  const labels=meses.map(m=>{const p=m.slice(0,7).split('-');const mo=['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];return `${mo[parseInt(p[1])]} ${p[0].slice(2)}`;});
  const hAsig  =meses.map(m=>sum(byMes[m],'horas_asignadas'));
  const hFact  =meses.map(m=>sum(byMes[m],'horas_facturables'));
  const hNoFact=meses.map(m=>sum(byMes[m],'horas_no_facturables'));
  const hHund  =meses.map(m=>{const t=sumRow(byMes[m]);return Math.max(0,168*new Set(byMes[m].map(r=>r.consultor)).size-t.horas_facturables-t.horas_no_facturables);});

  if(chartInst)chartInst.destroy();
  const isLight=document.documentElement.dataset.theme==='light';
  const tick=isLight?'#656d76':'#8b949e';
  const grid=isLight?'#e8ecf0':'#1e2430';

  chartInst=new Chart(document.getElementById('chart').getContext('2d'),{
    type:'bar',
    data:{labels,datasets:[
      {label:'Asignadas',      data:hAsig,  type:'line', borderColor:'rgba(188,140,255,.9)', backgroundColor:'transparent', tension:.3, pointRadius:4, borderWidth:2, borderDash:[4,3]},
      {label:'Facturables',    data:hFact,  backgroundColor:'rgba(46,160,67,.7)',  borderRadius:3,stack:'h'},
      {label:'No Facturables', data:hNoFact,backgroundColor:'rgba(227,179,65,.6)',borderRadius:3,stack:'h'},
      {label:'Capacidad Ociosa',data:hHund, backgroundColor:'rgba(248,81,73,.4)', borderRadius:3,stack:'h'},
    ]},
    options:{
      responsive:true,maintainAspectRatio:true,
      plugins:{legend:{labels:{color:tick,font:{size:10},padding:14}}},
      scales:{
        x:{ticks:{color:tick,font:{size:9}},grid:{color:grid},stacked:true},
        y:{ticks:{color:tick,font:{size:9},callback:v=>v+'h'},grid:{color:grid},stacked:true},
      }
    }
  });
}

// ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
let sortKey='horas_facturables', sortAsc=false;

const COLS=[
  {key:'margen_usd',           label:'Margen USD',    f:fmt,  cls:'', derived:r=>r.revenue_generado-r.costo_total},
  {key:'horas_asignadas',      label:'Asignadas',     f:fmtH, cls:'neu'},
  {key:'horas_ejecutadas',     label:'Ejecutadas',    f:fmtH, cls:''},
  {key:'horas_facturables',    label:'Facturables',   f:fmtH, cls:'pos'},
  {key:'horas_no_facturables', label:'No Fact.',      f:fmtH, cls:'warn'},
  {key:'billing_rate_usd',     label:'Tarifa/h',      f:fmtR, cls:'neu'},
  {key:'costo_hora',           label:'Costo/h',       f:fmtR, cls:''},
  {key:'costo_directo',        label:'C.Directo',     f:fmt,  cls:''},
  {key:'costo_no_facturable',  label:'C.No Fact.',    f:fmt,  cls:'warn'},
  {key:'costo_hundido',        label:'C.Hundido',     f:fmt,  cls:'neg'},
  {key:'costo_total',          label:'C.Total',       f:fmt,  cls:''},
  {key:'revenue_generado',     label:'Revenue',       f:fmt,  cls:'pos'},
];

function renderTable(rows){
  const byRM=groupBy(rows,'revenue_manager');
  const rms=Object.keys(byRM).sort();

  const head=`<tr>
    <th class="left" style="min-width:180px">Consultor / Proyecto</th>
    ${COLS.map(c=>`<th onclick="setSort('${c.key}')" class="${sortKey===c.key?'active':''}">${c.label}<span class="sort-icon ${sortKey===c.key?'on':''}">${sortKey===c.key?(sortAsc?'▲':'▼'):'⬍'}</span></th>`).join('')}
  </tr>`;

  const maxFact=Math.max(...rows.map(r=>+r.horas_facturables||0),1);

  let bodyHtml='';
  rms.forEach(rm=>{
    const rmRows=byRM[rm];
    const rmT=sumRow(rmRows);
    // RM header row
    bodyHtml+=`<tr style="background:rgba(188,140,255,.06)">
      <td class="left name" colspan="1" style="color:var(--purple);font-size:9px;letter-spacing:1px;padding:10px 12px">▸ ${rm}</td>
      ${COLS.map(c=>`<td class="${c.cls}" style="font-weight:600;font-size:9px">${c.key==='billing_rate_usd'||c.key==='costo_hora'?'—':c.f(c.derived?c.derived(rmT):rmT[c.key])}</td>`).join('')}
    </tr>`;

    const byConsultor=groupBy(rmRows,'consultor');
    const consultores=Object.keys(byConsultor).sort();

    consultores.forEach((con,ci)=>{
      const conId=`c${rms.indexOf(rm)}-${ci}`;
      const conRows=byConsultor[con];
      const conT=sumRow(conRows);
      const tipo=conRows[0]?.tipo_empleado||'';
      const dep=conRows[0]?.departamento||'—';
      const util=conT.horas_ejecutadas?conT.horas_facturables/conT.horas_ejecutadas*100:0;

      // Consultor row (start collapsed)
      const tipoColor = tipo==='Employee' ? 'var(--green)' : tipo==='Contractor' ? 'var(--amber)' : 'var(--text3)';
      const tipoBadge = tipo
        ? `<span style="display:inline-block;font-size:8px;letter-spacing:.5px;padding:1px 5px;margin-left:6px;border:1px solid ${tipoColor};color:${tipoColor};border-radius:2px;text-transform:uppercase;font-weight:600">${tipo}</span>`
        : '';
      bodyHtml+=`<tr class="con-row" data-con="${conId}" data-collapsed="1" style="background:var(--bg3);cursor:pointer" onclick="toggleCon('${conId}',this)">
        <td class="left name" style="padding-left:20px;font-size:10px">
          <span class="tg-arrow" style="display:inline-block;width:12px;color:var(--text3)">▸</span>
          ${con}${tipoBadge}
          <div class="mini-bar"><div class="mini-fill" style="width:${Math.min(100,util)}%;background:${util>=70?'var(--green)':util>=40?'var(--amber)':'var(--red)'}"></div></div>
        </td>
        ${COLS.map(c=>`<td class="${c.cls} ${c.key==='margen_usd'?(conT.margen_usd>0?'pos':conT.margen_usd<0?'neg':''):''}" style="font-weight:600">${c.key==='billing_rate_usd'||c.key==='costo_hora'?'—':c.f(c.derived?c.derived(conT):conT[c.key])}</td>`).join('')}
      </tr>`;

      // Mes subtotal → proyectos del mes
      const MO=['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
      const fmtMes=m=>{if(!m) return '—'; const p=String(m).slice(0,7).split('-'); return `${MO[parseInt(p[1])]||p[1]} ${p[0].slice(2)}`;};
      const mesKey=r=>String(r.mes||'').slice(0,7);
      const byMesC=groupBy(conRows.map(r=>({...r,_mk:mesKey(r)})),'_mk');
      const meses=Object.keys(byMesC).sort();
      meses.forEach((mk,mi)=>{
        const mesId=`${conId}-m${mi}`;
        const mRows=byMesC[mk];
        const mT=sumRow(mRows);
        // Mes subtotal row (start collapsed and hidden — consultor is collapsed)
        bodyHtml+=`<tr class="mes-row" data-con-child="${conId}" data-mes="${mesId}" data-collapsed="1" style="background:var(--bg2);cursor:pointer;display:none" onclick="toggleMes('${mesId}',this)">
          <td class="left" style="padding-left:36px;font-size:9px;color:var(--text);font-weight:600">
            <span class="tg-arrow" style="display:inline-block;width:12px;color:var(--text3)">▸</span>
            ${fmtMes(mk)}
          </td>
          ${COLS.map(c=>`<td class="${c.cls||''} ${c.key==='margen_usd'?(mT.margen_usd>0?'pos':mT.margen_usd<0?'neg':''):''}" style="font-weight:600">${c.key==='billing_rate_usd'||c.key==='costo_hora'?'—':c.f(c.derived?c.derived(mT):mT[c.key])}</td>`).join('')}
        </tr>`;
        // Proyectos del mes (ordenados)
        const sorted=[...mRows].sort((a,b)=>sortAsc?(+a[sortKey]||0)-(+b[sortKey]||0):(+b[sortKey]||0)-(+a[sortKey]||0));
        sorted.forEach(r=>{
          const label=PROJ_LABEL[r.proyecto]||r.proyecto;
          const row={...r, margen_usd:(+r.revenue_generado||0)-(+r.costo_total||0)};
          bodyHtml+=`<tr class="proj-row" data-con-child="${conId}" data-mes-child="${mesId}" style="display:none">
            <td class="left" style="padding-left:60px;font-size:9px;color:var(--text3)">${label}</td>
            ${COLS.map(c=>`<td class="${c.cls||''} ${c.key==='margen_usd'?(row.margen_usd>0?'pos':row.margen_usd<0?'neg':''):''}">${c.derived?c.f(c.derived(row)):c.f(+row[c.key]||0)}</td>`).join('')}
          </tr>`;
        });
      });
    });
  });

  // Grand total
  const grand=sumRow(rows);
  const nCon=new Set(rows.map(r=>r.consultor)).size;
  bodyHtml+=`<tr class="grand-total">
    <td class="left">TOTAL — ${nCon} consultores</td>
    ${COLS.map(c=>`<td class="${c.key==='margen_usd'?(grand.margen_usd>0?'pos':grand.margen_usd<0?'neg':''):''}">${c.key==='billing_rate_usd'||c.key==='costo_hora'?'—':c.f(c.derived?c.derived(grand):grand[c.key])}</td>`).join('')}
  </tr>`;

  document.getElementById('tbl-count').textContent=`${rows.length} registros · ${new Set(rows.map(r=>r.consultor)).size} consultores`;
  document.getElementById('tbl-wrap').innerHTML=`<table><thead>${head}</thead><tbody>${bodyHtml}</tbody></table>`;
}

function renderMatrix(rows){
  if(!rows.length){document.getElementById('matrix-wrap').innerHTML='<div style="padding:20px;color:var(--text3);font-size:11px">Sin datos de asignación</div>';return;}
  const MO=['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  const today=new Date().toISOString().slice(0,7);
  const meses=[...new Set(rows.map(r=>r.mes?r.mes.slice(0,7):null).filter(Boolean))].sort();

  const byRM=groupBy(rows,'revenue_manager');
  const rms=Object.keys(byRM).sort();

  // Cell data: asignadas + ejecutadas + estado
  function cellData(mesRows){
    return {
      asig: mesRows.reduce((a,r)=>a+(+r.horas_asignadas||0),0),
      ejec: mesRows.reduce((a,r)=>a+(+r.horas_ejecutadas||0),0),
      futuro: mesRows.every(r=>r.estado==='futuro')
    };
  }

  function cellStyle(pct, futuro){
    if(pct<=0) return 'color:var(--text3)';
    const alpha=futuro?'.12':'.2';
    if(pct>100) return `background:rgba(124,159,255,${alpha});color:var(--blue)`;
    if(pct>=80)  return `background:rgba(46,160,67,${alpha});color:var(--green)`;
    if(pct>=50)  return `background:rgba(227,179,65,${alpha});color:var(--amber)`;
    return `background:rgba(248,81,73,${alpha});color:var(--red)`;
  }

  const mesLabel=m=>{
    const p=m.split('-');
    const isFut=m>today;
    return `<span style="${isFut?'color:var(--text3)':''}">${MO[parseInt(p[1])]} ${p[0].slice(2)}${isFut?' ⬇':''}</span>`;
  };

  const head=`<tr>
    <th class="left" style="min-width:170px;position:sticky;left:0;z-index:2;background:var(--bg2)">Consultor</th>
    ${meses.map(m=>`<th style="min-width:72px;text-align:center">${mesLabel(m)}</th>`).join('')}
    <th style="min-width:65px">Total h</th>
    <th style="min-width:55px">Prom %</th>
  </tr>`;

  let body='';
  rms.forEach(rm=>{
    const rmRows=byRM[rm];
    const byC=groupBy(rmRows,'consultor');
    const cons=Object.keys(byC).sort();

    // RM totals row
    const rmCell={};
    meses.forEach(m=>{rmCell[m]=cellData(rmRows.filter(r=>r.mes&&r.mes.startsWith(m)));});
    const rmTotal=Object.values(rmCell).reduce((a,c)=>a+c.asig,0);
    const rmActMes=meses.filter(m=>rmCell[m].asig>0);
    const rmPctAvg=rmActMes.length?rmActMes.reduce((a,m)=>a+(rmCell[m].asig/168*100),0)/rmActMes.length:0;

    body+=`<tr style="background:rgba(188,140,255,.06)">
      <td class="left name" style="color:var(--purple);font-size:9px;letter-spacing:1px;padding:10px 12px;position:sticky;left:0;z-index:1;background:rgba(20,12,40,.97)">▸ ${rm}</td>
      ${meses.map(m=>{const c=rmCell[m];const pct=c.asig/168*100;
        return `<td style="text-align:center;font-size:9px;font-weight:600;${cellStyle(pct,c.futuro)}">${c.asig?fmtH(c.asig):'—'}</td>`;
      }).join('')}
      <td style="text-align:center;font-size:9px;font-weight:700;color:var(--purple)">${fmtH(rmTotal)}</td>
      <td style="text-align:center;font-size:9px;font-weight:700;color:var(--purple)">${rmActMes.length?fmtP(rmPctAvg):'—'}</td>
    </tr>`;

    cons.forEach(con=>{
      const conRows=byC[con];
      const cell={};
      meses.forEach(m=>{cell[m]=cellData(conRows.filter(r=>r.mes&&r.mes.startsWith(m)));});
      const total=Object.values(cell).reduce((a,c)=>a+c.asig,0);
      const actMes=meses.filter(m=>cell[m].asig>0);
      const pctAvg=actMes.length?actMes.reduce((a,m)=>a+(cell[m].asig/168*100),0)/actMes.length:0;

      body+=`<tr>
        <td class="left" style="padding-left:20px;font-size:10px;font-weight:500;position:sticky;left:0;z-index:1;background:var(--bg2)">${con}</td>
        ${meses.map(m=>{
          const c=cell[m]; 
          const pct=c.asig/168*100;
          if(!c.asig) return `<td style="text-align:center"><span style="opacity:.2;font-size:9px">—</span></td>`;
          return `<td style="text-align:center;padding:4px 3px;${cellStyle(pct,c.futuro)}">
            <div style="font-size:9px;font-weight:700">${fmtH(c.asig)}</div>
            <div style="font-size:8px;opacity:.85">${fmtP(pct)}</div>
            ${!c.futuro&&c.ejec?`<div style="font-size:7px;opacity:.6">${fmtH(c.ejec)} ej.</div>`:''}
          </td>`;
        }).join('')}
        <td style="text-align:center;font-size:9px;font-weight:600">${fmtH(total)}</td>
        <td style="text-align:center;font-size:9px;font-weight:600;${cellStyle(pctAvg,false)}">${actMes.length?fmtP(pctAvg):'—'}</td>
      </tr>`;
    });
  });

  const legend=`<div style="display:flex;gap:16px;padding:10px 14px;border-top:1px solid var(--border);font-size:9px;flex-wrap:wrap;align-items:center">
    <span style="color:var(--blue)">● >100% sobreasignado</span>
    <span style="color:var(--green)">● 80-100% óptimo</span>
    <span style="color:var(--amber)">● 50-80% parcial</span>
    <span style="color:var(--red)">● <50% subutilizado</span>
    <span style="color:var(--text3);margin-left:8px">⬇ mes futuro (sin ejecución aún)</span>
  </div>`;

  document.getElementById('matrix-wrap').innerHTML=
    `<div style="overflow-x:auto"><table style="border-collapse:collapse;width:100%"><thead>${head}</thead><tbody>${body}</tbody></table></div>${legend}`;
}

function toggleCon(conId, el){
  event.stopPropagation();
  const collapsed = el.dataset.collapsed === '1';
  el.dataset.collapsed = collapsed ? '0' : '1';
  el.querySelector('.tg-arrow').textContent = collapsed ? '▾' : '▸';
  if (collapsed) {
    // expand: show mes subtotals only, keep their projects collapsed
    document.querySelectorAll(`tr.mes-row[data-con-child="${conId}"]`).forEach(mr => {
      mr.style.display = '';
      mr.dataset.collapsed = '1';
      mr.querySelector('.tg-arrow').textContent = '▸';
    });
    document.querySelectorAll(`tr.proj-row[data-con-child="${conId}"]`).forEach(pr => {
      pr.style.display = 'none';
    });
  } else {
    // collapse everything inside
    document.querySelectorAll(`tr[data-con-child="${conId}"]`).forEach(r => {
      r.style.display = 'none';
    });
  }
}
function toggleMes(mesId, el){
  event.stopPropagation();
  const collapsed = el.dataset.collapsed === '1';
  el.dataset.collapsed = collapsed ? '0' : '1';
  el.querySelector('.tg-arrow').textContent = collapsed ? '▾' : '▸';
  document.querySelectorAll(`tr.proj-row[data-mes-child="${mesId}"]`).forEach(r => {
    r.style.display = collapsed ? '' : 'none';
  });
}

function setSort(key){
  if(sortKey===key) sortAsc=!sortAsc; else{sortKey=key;sortAsc=false;}
  renderTable(ROWS);
}

// ────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────────
function toggleTheme(){
  const html=document.documentElement;
  const isLight=html.dataset.theme==='light';
  html.dataset.theme=isLight?'dark':'light';
  document.getElementById('theme-btn').textContent=isLight?'☀ Claro':'☾ Oscuro';
  localStorage.setItem('con-theme',html.dataset.theme);
  if(chartInst)renderChart(ROWS);
}

async function init(){
  const saved=localStorage.getItem('con-theme')||'dark';
  document.documentElement.dataset.theme=saved;
  document.getElementById('theme-btn').textContent=saved==='light'?'☾ Oscuro':'☀ Claro';
  // Mostrar mes actual de referencia
  const td=new Date();
  const MO=['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
  const tag=document.getElementById('mes-actual-tag');
  if(tag) tag.textContent = `(hoy: ${MO[td.getMonth()+1]} ${String(td.getFullYear()).slice(2)} — meses pasados=facturables, mes actual y futuros=asignadas)`;
  await loadInitialOptions();
}
init();
</script>
</body>
</html>$seed$, $seed$$seed$, $seed$replicon$seed$, $seed$shared$seed$, $seed${consultor_asignacion,consultor_mensual}$seed$::text[], NOW())
ON CONFLICT (name) DO NOTHING;

INSERT INTO analytic_apps (name, title, html, description, cartridge_id, visibility, datasets_used, updated_at)
VALUES ($seed$pnl_ejecutivo$seed$, $seed$P&L Ejecutivo$seed$, $seed$<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>P&L Ejecutivo</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
:root{
  --bg:#0d1117;--bg2:#161b22;--bg3:#1e2736;--border:#30363d;
  --text1:#e6edf3;--text2:#8b949e;--text3:#58626d;
  --green:#2ea043;--green-glow:#39ff14;
  --blue:#7c9fff;--amber:#e3b341;--red:#f85149;
  --card-r:8px;
}
[data-theme=light]{
  --bg:#f0f2f5;--bg2:#ffffff;--bg3:#e8ecf1;--border:#d0d7de;
  --text1:#1f2328;--text2:#656d76;--text3:#a0aab4;
  --green:#1a7f37;--green-glow:#1a7f37;--blue:#0969da;--amber:#9a6700;--red:#cf222e;
}
*{box-sizing:border-box;margin:0;padding:0}
body{background:var(--bg);color:var(--text1);font-family:system-ui,-apple-system,sans-serif;min-height:100vh;transition:background .2s,color .2s}

/* ── Header ── */
.hdr{background:var(--bg2);border-bottom:1px solid var(--border);padding:16px 28px;display:flex;align-items:center;gap:16px}
.hdr-title{font-size:13px;font-weight:700;letter-spacing:1px;color:var(--blue);flex:1}
.hdr-sub{font-size:10px;color:var(--text2);letter-spacing:1px}
.theme-btn{background:transparent;border:1px solid var(--border);color:var(--text2);padding:5px 12px;font-size:10px;border-radius:20px;cursor:pointer}
.theme-btn:hover{border-color:var(--blue);color:var(--blue)}

/* ── Filters ── */
.filters{background:var(--bg2);border-bottom:1px solid var(--border);padding:12px 28px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}
.filter-group{display:flex;align-items:center;gap:6px}
label{font-size:10px;color:var(--text2);white-space:nowrap;font-weight:600;letter-spacing:.5px}
/* ── Multi-select ── */
.ms-wrap{position:relative;min-width:180px}
.ms-trigger{background:var(--bg);border:1px solid var(--border);color:var(--text1);padding:7px 30px 7px 12px;font-size:11px;border-radius:6px;cursor:pointer;width:100%;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block}
.ms-trigger:focus,.ms-trigger.open{outline:none;border-color:var(--blue)}
.ms-trigger::after{content:'▾';position:absolute;right:10px;top:50%;transform:translateY(-50%);color:var(--text2);font-size:10px;pointer-events:none}
.ms-dropdown{position:absolute;top:calc(100% + 4px);left:0;right:0;background:var(--bg2);border:1px solid var(--blue);border-radius:6px;z-index:999;max-height:240px;overflow-y:auto;box-shadow:0 8px 24px rgba(0,0,0,.4);display:none}
.ms-dropdown.open{display:block}
.ms-search{width:100%;background:var(--bg);border:none;border-bottom:1px solid var(--border);color:var(--text1);padding:8px 12px;font-size:10px;outline:none}
.ms-opt{display:flex;align-items:center;gap:8px;padding:7px 12px;cursor:pointer;font-size:10px}
.ms-opt:hover{background:var(--bg3)}
.ms-opt input[type=checkbox]{accent-color:var(--blue);width:12px;height:12px;flex-shrink:0}
.ms-actions{display:flex;gap:6px;padding:6px 10px;border-top:1px solid var(--border)}
.ms-action-btn{flex:1;background:transparent;border:1px solid var(--border);color:var(--text2);padding:4px;font-size:9px;border-radius:4px;cursor:pointer}
.ms-action-btn:hover{border-color:var(--blue);color:var(--blue)}
.btn{padding:8px 20px;font-size:11px;font-weight:600;border-radius:6px;cursor:pointer;border:none;letter-spacing:.5px}
.btn-primary{background:var(--blue);color:#fff}
.btn-primary:hover{opacity:.9}
.btn-primary:disabled{opacity:.4;cursor:not-allowed}
.spinner{display:inline-block;width:10px;height:10px;border:2px solid rgba(255,255,255,.3);border-top-color:#fff;border-radius:50%;animation:spin .6s linear infinite;vertical-align:middle;margin-right:6px}
@keyframes spin{to{transform:rotate(360deg)}}

/* ── Content ── */
.content{padding:24px 28px;max-width:1400px;margin:0 auto}

/* ── Placeholder ── */
.placeholder{text-align:center;padding:100px 20px;color:var(--text2)}
.placeholder-icon{font-size:40px;margin-bottom:16px;opacity:.3}
.placeholder h2{font-size:14px;font-weight:400;margin-bottom:8px;color:var(--text2)}
.placeholder p{font-size:11px;color:var(--text3)}

/* ── KPI strip ── */
.kpi-strip{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:14px;margin-bottom:24px}
.kpi-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r);padding:18px 20px;position:relative;overflow:hidden}
.kpi-card::before{content:'';position:absolute;top:0;left:0;width:3px;height:100%;background:var(--accent,var(--border))}
.kpi-label{font-size:9px;color:var(--text2);letter-spacing:1.5px;font-weight:600;margin-bottom:8px;text-transform:uppercase}
.kpi-val{font-size:22px;font-weight:700;color:var(--text1);line-height:1}
.kpi-sub{font-size:10px;color:var(--text3);margin-top:5px}
.kpi-badge{display:inline-block;padding:2px 8px;border-radius:10px;font-size:9px;font-weight:700;letter-spacing:.5px}
.badge-green{background:rgba(46,160,67,.15);color:var(--green)}
.badge-amber{background:rgba(227,179,65,.15);color:var(--amber)}
.badge-red{background:rgba(248,81,73,.15);color:var(--red)}
.badge-blue{background:rgba(124,159,255,.15);color:var(--blue)}

/* ── Alert banner ── */
.alert-banner{background:rgba(248,81,73,.08);border:1px solid rgba(248,81,73,.3);border-radius:var(--card-r);padding:14px 18px;margin-bottom:24px;display:flex;gap:12px;align-items:flex-start}
.alert-icon{font-size:16px;flex-shrink:0;margin-top:1px}
.alert-title{font-size:11px;font-weight:700;color:var(--red);margin-bottom:6px}
.alert-items{display:flex;flex-wrap:wrap;gap:6px}
.alert-chip{background:rgba(248,81,73,.12);border:1px solid rgba(248,81,73,.25);border-radius:4px;padding:3px 10px;font-size:10px;color:var(--red)}

/* ── Section ── */
.section{margin-bottom:28px}
.section-hdr{display:flex;align-items:baseline;gap:10px;margin-bottom:14px}
.section-title{font-size:11px;font-weight:700;letter-spacing:1px;color:var(--text2);text-transform:uppercase}
.section-count{font-size:10px;color:var(--text3)}

/* ── Project cards ── */
.proj-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(320px,1fr));gap:14px}
.proj-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r);padding:16px 18px;transition:border-color .15s}
.proj-card:hover{border-color:var(--blue)}
.proj-card-top{display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:10px}
.proj-name{font-size:11px;font-weight:700;color:var(--text1);line-height:1.3;flex:1;margin-right:8px}
.proj-client{font-size:9px;color:var(--text2);margin-top:3px}
.proj-type{font-size:8px;color:var(--text3);letter-spacing:.5px;margin-top:2px}
.traffic-light{width:10px;height:10px;border-radius:50%;flex-shrink:0;margin-top:3px;box-shadow:0 0 6px var(--tl-color,transparent)}
.tl-green{background:var(--green);--tl-color:var(--green)}
.tl-amber{background:var(--amber);--tl-color:var(--amber)}
.tl-red{background:var(--red);--tl-color:var(--red)}
.tl-gray{background:var(--text3)}
.proj-metrics{display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:10px}
.pm-item{text-align:center}
.pm-val{font-size:13px;font-weight:700;color:var(--text1)}
.pm-label{font-size:8px;color:var(--text3);letter-spacing:.5px;margin-top:2px}
.progress-wrap{margin-top:8px}
.progress-label{display:flex;justify-content:space-between;margin-bottom:4px}
.progress-label span{font-size:9px;color:var(--text2)}
.progress-bar{height:4px;background:var(--bg3);border-radius:2px;overflow:hidden}
.progress-fill{height:100%;border-radius:2px;transition:width .4s}
.fill-green{background:var(--green)}
.fill-amber{background:var(--amber)}
.fill-red{background:var(--red)}
.fill-blue{background:var(--blue)}

/* ── Trend chart ── */
.chart-card{background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r);padding:20px}
canvas{max-height:260px}

/* ── Summary table ── */
.tbl-wrap{overflow-x:auto;background:var(--bg2);border:1px solid var(--border);border-radius:var(--card-r)}
table{width:100%;border-collapse:collapse;font-size:10px}
th{padding:10px 14px;text-align:right;color:var(--text2);font-size:9px;letter-spacing:1px;border-bottom:1px solid var(--border);white-space:nowrap;font-weight:600}
th.left{text-align:left}
td{padding:9px 14px;text-align:right;border-bottom:1px solid var(--bg3);white-space:nowrap}
[data-theme=light] td{border-bottom:1px solid var(--bg3)}
td.left{text-align:left}
tr:last-child td{border-bottom:none}
tr:hover td{background:var(--bg3)}
.total-row td{border-top:2px solid var(--border);font-weight:700;color:var(--blue)}
.sort-btn{cursor:pointer;user-select:none}
.sort-btn:hover{color:var(--blue)}
.pos{color:var(--green)}.neg{color:var(--red)}.neu{color:var(--blue)}
</style>
</head>
<body>

<div class="hdr">
  <div>
    <div class="hdr-title">P&amp;L EJECUTIVO</div>
    <div class="hdr-sub">Visión por Revenue Manager &middot; Año Fiscal mar–feb</div>
  </div>
  <button class="theme-btn" id="theme-btn" onclick="toggleTheme()">☀ Claro</button>
</div>

<div class="filters">
  <div class="filter-group">
    <label>Revenue Manager</label>
    <div class="ms-wrap" id="ms-rm"></div>
  </div>
  <div class="filter-group">
    <label>Año Fiscal</label>
    <div class="ms-wrap" id="ms-yr"></div>
  </div>
  <div class="filter-group">
    <label>Cliente</label>
    <div class="ms-wrap" id="ms-cl"></div>
  </div>
  <button class="btn btn-primary" id="btn-filter" onclick="applyFilter()">Ver resultados</button>
</div>

<div class="content">

  <div id="placeholder" class="placeholder">
    <div class="placeholder-icon">📊</div>
    <h2>Selecciona un Revenue Manager y Año Fiscal</h2>
    <p>Presiona <strong>Ver resultados</strong> para cargar el portafolio</p>
  </div>

  <div id="main" style="display:none">

    <!-- KPIs -->
    <div class="kpi-strip" id="kpis"></div>

    <!-- Alertas -->
    <div id="alerts"></div>

    <!-- Tendencia -->
    <div class="section">
      <div class="section-hdr"><span class="section-title">Tendencia del período</span></div>
      <div class="chart-card"><canvas id="chart"></canvas></div>
    </div>

    <!-- Portfolio cards -->
    <div class="section">
      <div class="section-hdr">
        <span class="section-title">Portafolio de proyectos</span>
        <span class="section-count" id="proj-count"></span>
      </div>
      <div class="proj-grid" id="proj-grid"></div>
    </div>

    <!-- Tabla resumen -->
    <div class="section">
      <div class="section-hdr"><span class="section-title">Resumen consolidado</span></div>
      <div class="tbl-wrap" id="tbl-wrap"></div>
    </div>

  </div>
</div>

<script>
let ROWS = [];
let chartInst = null;
const PROJ_LABEL = {};

// ── Format helpers ──────────────────────────────────────────────────────────
const fmt  = n => n==null?'—':'$'+Number(n).toLocaleString('es-MX',{minimumFractionDigits:0,maximumFractionDigits:0});
const fmtD = n => n==null?'—':'$'+Number(n).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtH = n => n==null?'—':Number(n).toLocaleString('es-MX',{minimumFractionDigits:0,maximumFractionDigits:0})+' h';
const fmtP = n => n==null?'—':Number(n).toFixed(1)+'%';
const sign  = n => n>0?'+':'';

function fiscalYear(s){
  const p=(s||'').slice(0,7).split('-');
  const yr=parseInt(p[0])||0,mo=parseInt(p[1])||0;
  return mo<=2?yr-1:yr;
}
function groupBy(arr,key){return arr.reduce((m,r)=>{(m[r[key]]=m[r[key]]||[]).push(r);return m;},{});}
function sumRows(rows){
  const financial=['revenue_usd','facturacion_mes_usd','wip_usd','costo_directo','costo_hundido','costo_total','margen_bruto_usd'];
  const hours=['horas_facturables','horas_totales'];
  const a={revenue_usd:null,facturacion_mes_usd:null,wip_usd:null,costo_directo:null,costo_hundido:null,costo_total:null,margen_bruto_usd:null,horas_facturables:null,horas_totales:null};
  const ready=rows.filter(r=>r.financial_status==='ready');
  financial.forEach(k=>a[k]=ready.length&&ready.every(r=>r[k]!=null)?ready.reduce((sum,r)=>sum+Number(r[k]),0):null);
  hours.forEach(k=>a[k]=rows.length&&rows.every(r=>r[k]!=null)?rows.reduce((sum,r)=>sum+Number(r[k]),0):null);
  a.margen_bruto_pct=a.revenue_usd?(a.margen_bruto_usd/a.revenue_usd*100):null;
  return a;
}
function trafficClass(pct){
  if(pct==null) return 'tl-gray';
  if(pct>=20)   return 'tl-green';
  if(pct>=10)   return 'tl-amber';
  return 'tl-red';
}
function badgeClass(pct){
  if(pct==null) return 'badge-blue';
  if(pct>=20)   return 'badge-green';
  if(pct>=10)   return 'badge-amber';
  return 'badge-red';
}
function badgeLabel(pct){
  if(pct==null) return 'DATOS INSUFICIENTES';
  if(pct>=20)   return '✓ BUENO';
  if(pct>=10)   return '⚠ ALERTA';
  return '✕ CRÍTICO';
}
function fillClass(pct){
  if(pct==null||pct<0) return 'fill-red';
  if(pct>=20) return 'fill-green';
  if(pct>=10) return 'fill-amber';
  return 'fill-red';
}

// ── Multi-select component ───────────────────────────────────────────────────
const MS = {};

function msCreate(containerId, placeholder='Todos'){
  const wrap=document.getElementById(containerId);
  wrap.innerHTML=`
    <button class="ms-trigger" onclick="msToggle('${containerId}',event)">${placeholder}</button>
    <div class="ms-dropdown" id="${containerId}-dd">
      <input class="ms-search" placeholder="Buscar…" oninput="msFilter('${containerId}',this.value)">
      <div id="${containerId}-list"></div>
      <div class="ms-actions">
        <button class="ms-action-btn" onclick="msAll('${containerId}',true)">Todo</button>
        <button class="ms-action-btn" onclick="msAll('${containerId}',false)">Ninguno</button>
      </div>
    </div>`;
  MS[containerId]={selected:new Set(),options:[],placeholder};
  document.addEventListener('click',e=>{
    if(!wrap.contains(e.target)) msClose(containerId);
  });
}

function msToggle(id,ev){
  if(ev) ev.stopPropagation();
  const dd=document.getElementById(id+'-dd');
  const btn=document.querySelector(`#${id} .ms-trigger`);
  const isOpen=dd.classList.contains('open');
  Object.keys(MS).forEach(k=>msClose(k));
  if(!isOpen){dd.classList.add('open');btn.classList.add('open');}
}
function msClose(id){
  document.getElementById(id+'-dd')?.classList.remove('open');
  document.querySelector(`#${id} .ms-trigger`)?.classList.remove('open');
}

function msSetOptions(id, options, labelFn=null){
  MS[id].options=options;
  msRender(id,'');
}

function msRender(id, search){
  const {options,selected}=MS[id];
  const filtered=search?options.filter(o=>String(o).toLowerCase().includes(search.toLowerCase())):options;
  document.getElementById(id+'-list').innerHTML=filtered.map(o=>`
    <label class="ms-opt">
      <input type="checkbox" value="${o}" ${selected.has(String(o))?'checked':''} onchange="msCheck('${id}','${String(o).replace(/'/g,"\\'")}',this.checked)">
      <span>${o}</span>
    </label>`).join('');
}

function msFilter(id,search){msRender(id,search);}

function msCheck(id,val,checked){
  if(checked) MS[id].selected.add(val); else MS[id].selected.delete(val);
  msUpdateLabel(id);
  if(id==='ms-rm'||id==='ms-yr'){clearTimeout(MS._t);MS._t=setTimeout(refreshClientes,400);}
}

function msAll(id,sel){
  const s=MS[id].selected;
  if(sel) MS[id].options.forEach(o=>s.add(String(o))); else s.clear();
  msRender(id,'');
  msUpdateLabel(id);
  if(id==='ms-rm'||id==='ms-yr'){clearTimeout(MS._t);MS._t=setTimeout(refreshClientes,400);}
}

function msUpdateLabel(id){
  const {selected,placeholder}=MS[id];
  const btn=document.querySelector(`#${id} .ms-trigger`);
  if(!selected.size) btn.textContent=placeholder;
  else if(selected.size===1) btn.textContent=[...selected][0];
  else btn.textContent=`${selected.size} seleccionados`;
}

function msGet(id){ return [...MS[id].selected]; }

// ── Selectors ───────────────────────────────────────────────────────────────
async function loadInitialOptions(){
  msCreate('ms-rm','Todos');
  msCreate('ms-yr','Selecciona…');
  msCreate('ms-cl','Todos');

  try{
    const r=await fetch('/api/data/pnl_mensual/options?columns=revenue_manager');
    const opts=await r.json();
    msSetOptions('ms-rm', opts.revenue_manager||[]);
  }catch(e){}

  try{
    const r=await fetch('/api/data/pnl_mensual/query',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters:{},limit:5000,columns:['mes']})
    });
    const rows=await r.json();
    if(Array.isArray(rows)){
      const fys=[...new Set(rows.map(r=>fiscalYear(r.mes)).filter(Boolean))].sort().reverse();
      msSetOptions('ms-yr', fys, y=>`AF${y} (mar ${y} – feb ${y+1})`);
      // override render to show custom labels
      const opts=fys;
      MS['ms-yr'].options=opts;
      document.getElementById('ms-yr-list').innerHTML=opts.map(y=>`
        <label class="ms-opt">
          <input type="checkbox" value="${y}" onchange="msCheck('ms-yr','${y}',this.checked)">
          <span>AF${y} &nbsp;<span style="color:var(--text3);font-size:9px">mar ${y} – feb ${y+1}</span></span>
        </label>`).join('');
    }
  }catch(e){}

  // Load clientes (all)
  try{
    const r=await fetch('/api/data/pnl_mensual/query',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters:{},limit:5000,columns:['cliente']})
    });
    const rows=await r.json();
    if(Array.isArray(rows)){
      const cls=[...new Set(rows.map(r=>r.cliente).filter(Boolean))].sort();
      msSetOptions('ms-cl', cls);
    }
  }catch(e){}
}

async function refreshClientes(){
  const rm=msGet('ms-rm'),yr=msGet('ms-yr').map(Number);
  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  try{
    const r=await fetch('/api/data/pnl_mensual/query',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:5000,columns:['cliente']})});
    const rows=await r.json();
    if(!Array.isArray(rows)) return;
    const prevCl=msGet('ms-cl');
    const cls=[...new Set(rows.map(r=>r.cliente).filter(Boolean))].sort();
    msSetOptions('ms-cl',cls);
    prevCl.forEach(v=>{if(cls.includes(v))MS['ms-cl'].selected.add(v);}); msUpdateLabel('ms-cl');
  }catch(e){}
}

// ── Main query ──────────────────────────────────────────────────────────────
async function applyFilter(){
  const rm=msGet('ms-rm');
  const yr=msGet('ms-yr').map(Number);
  const cl=msGet('ms-cl');

  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  if(cl.length) filters.cliente=cl.length===1?cl[0]:cl;

  const btn=document.getElementById('btn-filter');
  btn.innerHTML='<span class="spinner"></span>Cargando…';
  btn.disabled=true;

  try{
    const r=await fetch('/api/data/pnl_mensual/query',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:5000})
    });
    ROWS=await r.json();
    if(!Array.isArray(ROWS)) ROWS=[];
    ROWS.forEach(r=>{
      if(r.proyecto&&!PROJ_LABEL[r.proyecto])
        PROJ_LABEL[r.proyecto]=r.project_name?`${r.proyecto} — ${r.project_name}`:r.proyecto;
    });
    document.getElementById('placeholder').style.display='none';
    document.getElementById('main').style.display='';
    render();
  }catch(e){alert('Error: '+e.message);}
  finally{btn.textContent='Ver resultados';btn.disabled=false;}
}

// ── Render ──────────────────────────────────────────────────────────────────
function render(){
  renderKPIs(ROWS);
  renderAlerts(ROWS);
  renderChart(ROWS);
  renderProjGrid(ROWS);
  renderTable(ROWS);
}

function renderKPIs(rows){
  const t=sumRows(rows);
  const byProj=groupBy(rows,'proyecto');
  const nProj=Object.keys(byProj).length;
  const nRisk=Object.values(byProj).filter(rs=>{
    const s=sumRows(rs);
    return s.revenue_usd>0&&(s.margen_bruto_pct==null||s.margen_bruto_pct<10);
  }).length;

  const items=[
    {label:'Revenue Total',  val:fmt(t.revenue_usd),  sub:fmtD(t.revenue_usd)+' USD', accent:'var(--blue)',   klass:''},
    {label:'Facturado',      val:fmt(t.facturacion_mes_usd), sub:'Emitido en el período', accent:'var(--green)', klass:''},
    {label:'WIP',            val:fmt(t.wip_usd),       sub:'Revenue pendiente de facturar', accent:t.wip_usd>=0?'var(--amber)':'var(--red)', klass:''},
    {label:'Margen Bruto',   val:fmtP(t.margen_bruto_pct), sub:fmt(t.margen_bruto_usd)+' USD',
      accent:t.margen_bruto_pct>=20?'var(--green)':t.margen_bruto_pct>=10?'var(--amber)':'var(--red)', klass:''},
    {label:'Costo Directo',  val:fmt(t.costo_directo),  sub:'Horas facturables × tarifa', accent:'var(--text3)', klass:''},
    {label:'Costo Ocioso',   val:fmt(t.costo_hundido),  sub:'Capacidad no utilizada', accent:'var(--amber)', klass:''},
    {label:'Proyectos',      val:nProj,                sub:`${nRisk} en riesgo`, accent:'var(--blue)', klass:''},
    {label:'Horas Facturas', val:fmtH(t.horas_facturables), sub:'de '+fmtH(t.horas_totales)+' totales', accent:'var(--blue)', klass:''},
  ];
  document.getElementById('kpis').innerHTML=items.map(({label,val,sub,accent})=>`
    <div class="kpi-card" style="--accent:${accent}">
      <div class="kpi-label">${label}</div>
      <div class="kpi-val">${val}</div>
      <div class="kpi-sub">${sub}</div>
    </div>`).join('');
}

function renderAlerts(rows){
  const byProj=groupBy(rows,'proyecto');
  const risk=Object.entries(byProj)
    .map(([p,rs])=>({proj:p,t:sumRows(rs),r0:rs[0]}))
    .filter(({t})=>t.revenue_usd>0&&(t.margen_bruto_pct==null||t.margen_bruto_pct<10))
    .sort((a,b)=>a.t.margen_bruto_pct-b.t.margen_bruto_pct);

  const el=document.getElementById('alerts');
  if(!risk.length){el.innerHTML='';return;}

  el.innerHTML=`
    <div class="alert-banner">
      <div class="alert-icon">⚠</div>
      <div>
        <div class="alert-title">${risk.length} proyecto${risk.length>1?'s':''} con margen crítico (&lt; 10%)</div>
        <div class="alert-items">
          ${risk.map(({proj,t,r0})=>`
            <div class="alert-chip">${PROJ_LABEL[proj]||proj} · ${fmtP(t.margen_bruto_pct)}</div>
          `).join('')}
        </div>
      </div>
    </div>`;
}

function renderChart(rows){
  const byMes=groupBy(rows,'mes');
  const meses=Object.keys(byMes).sort();
  const revenue=meses.map(m=>sumRows(byMes[m]).revenue_usd);
  const factura=meses.map(m=>sumRows(byMes[m]).facturacion_mes_usd);
  const margen =meses.map(m=>sumRows(byMes[m]).margen_bruto_pct);
  const labels =meses.map(m=>{
    const p=m.slice(0,7).split('-');
    const mo=['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    return `${mo[parseInt(p[1])]} ${p[0].slice(2)}`;
  });

  if(chartInst) chartInst.destroy();
  const isLight=document.documentElement.dataset.theme==='light';
  const tick=isLight?'#656d76':'#8b949e';
  const grid=isLight?'#e8ecf0':'#1e2430';

  chartInst=new Chart(document.getElementById('chart').getContext('2d'),{
    data:{labels,datasets:[
      {type:'bar', label:'Revenue',     data:revenue, backgroundColor:'rgba(124,159,255,.6)',borderRadius:4,yAxisID:'y'},
      {type:'bar', label:'Facturado',   data:factura, backgroundColor:'rgba(46,160,67,.5)', borderRadius:4,yAxisID:'y'},
      {type:'line',label:'Margen %',    data:margen,  borderColor:isLight?'#e3a000':'#e3b341',
       backgroundColor:'transparent',tension:.3,pointRadius:4,borderWidth:2,yAxisID:'y2'},
    ]},
    options:{
      responsive:true,maintainAspectRatio:true,
      interaction:{mode:'index',intersect:false},
      plugins:{
        legend:{labels:{color:tick,font:{size:10},padding:16}},
        tooltip:{callbacks:{
          label:ctx=>{
            const ds=ctx.dataset.label;
            return ds==='Margen %'?` ${ds}: ${(ctx.raw||0).toFixed(1)}%`
              :` ${ds}: $${Number(ctx.raw||0).toLocaleString('es-MX',{maximumFractionDigits:0})}`;
          }
        }}
      },
      scales:{
        x:{ticks:{color:tick,font:{size:9}},grid:{color:grid}},
        y:{ticks:{color:tick,font:{size:9},callback:v=>'$'+Number(v/1000).toFixed(0)+'k'},grid:{color:grid},position:'left'},
        y2:{ticks:{color:isLight?'#9a6700':'#e3b341',font:{size:9},callback:v=>v+'%'},grid:{display:false},position:'right'},
      }
    }
  });
}

function renderProjGrid(rows){
  const byProj=groupBy(rows,'proyecto');
  const projs=Object.entries(byProj)
    .map(([p,rs])=>({proj:p,t:sumRows(rs),r0:rs[0],
      avance:rs.reduce((best,r)=>r.mes>(best.mes||'')?r:best,{}).pct_avance_real
    }))
    .sort((a,b)=>(b.t.revenue_usd)-(a.t.revenue_usd));

  document.getElementById('proj-count').textContent=`${projs.length} proyectos`;

  const maxRev=Math.max(...projs.map(p=>p.t.revenue_usd),1);

  document.getElementById('proj-grid').innerHTML=projs.map(({proj,t,r0,avance})=>{
    const pct=t.margen_bruto_pct;
    const tlClass=trafficClass(pct);
    const bgClass=badgeClass(pct);
    const bgLabel=badgeLabel(pct);
    const revPct=Math.min(100,(t.revenue_usd/maxRev)*100);
    const tipo=r0.tipo_proyecto||'';
    const isFPP=tipo==='FPP';
    const label=PROJ_LABEL[proj]||proj;

    return `
    <div class="proj-card">
      <div class="proj-card-top">
        <div>
          <div class="proj-name">${label}</div>
          <div class="proj-client">${r0.cliente||'—'}</div>
          <div class="proj-type">${tipo}</div>
        </div>
        <div class="traffic-light ${tlClass}" title="${bgLabel}"></div>
      </div>

      <div class="proj-metrics">
        <div class="pm-item">
          <div class="pm-val">${fmt(t.revenue_usd)}</div>
          <div class="pm-label">Revenue</div>
        </div>
        <div class="pm-item">
          <div class="pm-val ${pct>=20?'pos':pct>=10?'':pct!=null?'neg':''}">${fmtP(pct)}</div>
          <div class="pm-label">Margen</div>
        </div>
        <div class="pm-item">
          <div class="pm-val ${t.wip_usd>=0?'neu':'neg'}">${fmt(t.wip_usd)}</div>
          <div class="pm-label">WIP</div>
        </div>
      </div>

      <div class="progress-wrap">
        <div class="progress-label">
          <span>Revenue vs portafolio</span>
          <span>${Math.round(revPct)}%</span>
        </div>
        <div class="progress-bar">
          <div class="progress-fill fill-blue" style="width:${revPct}%"></div>
        </div>
      </div>

      ${isFPP&&avance!=null?`
      <div class="progress-wrap" style="margin-top:6px">
        <div class="progress-label">
          <span>Avance real</span>
          <span>${fmtP(avance)}</span>
        </div>
        <div class="progress-bar">
          <div class="progress-fill ${fillClass(avance)}" style="width:${Math.min(100,avance||0)}%"></div>
        </div>
      </div>`:''}

      <div style="margin-top:10px;display:flex;justify-content:space-between;align-items:center">
        <span class="kpi-badge ${bgClass}">${bgLabel}</span>
        <span style="font-size:9px;color:var(--text3)">${fmtH(t.horas_facturables)} fact.</span>
      </div>
    </div>`;
  }).join('');
}

function renderTable(rows){
  const byProj=groupBy(rows,'proyecto');
  const projs=Object.entries(byProj)
    .map(([p,rs])=>({proj:p,t:sumRows(rs),r0:rs[0]}))
    .sort((a,b)=>(b.t.revenue_usd)-(a.t.revenue_usd));
  const grand=sumRows(rows);

  const cols=[
    {key:'revenue_usd',     label:'Revenue',      f:fmt,  color:v=>v>0?'pos':v<0?'neg':''},
    {key:'facturacion_mes_usd',label:'Facturado', f:fmt,  color:()=>''},
    {key:'wip_usd',         label:'WIP',          f:fmt,  color:v=>v>=0?'neu':'neg'},
    {key:'costo_directo',   label:'C. Directo',   f:fmt,  color:()=>''},
    {key:'costo_hundido',   label:'C. Ocioso',    f:fmt,  color:()=>''},
    {key:'costo_total',     label:'Costo Total',  f:fmt,  color:()=>''},
    {key:'margen_bruto_usd',label:'Margen USD',   f:fmt,  color:v=>v>0?'pos':v<0?'neg':''},
    {key:'margen_bruto_pct',label:'Margen %',     f:fmtP, color:v=>v>=20?'pos':v>=10?'':v!=null?'neg':''},
  ];

  const head=`<tr>
    <th class="left">Proyecto</th>
    <th class="left">Cliente</th>
    <th class="left">Tipo</th>
    ${cols.map(c=>`<th>${c.label}</th>`).join('')}
  </tr>`;

  const body=projs.map(({proj,t,r0})=>`
    <tr>
      <td class="left" style="font-size:9px;max-width:200px;overflow:hidden;text-overflow:ellipsis">${PROJ_LABEL[proj]||proj}</td>
      <td class="left" style="font-size:9px;color:var(--text2)">${r0.cliente||'—'}</td>
      <td class="left" style="font-size:9px;color:var(--text3)">${r0.tipo_proyecto||'—'}</td>
      ${cols.map(c=>`<td class="${c.color(t[c.key])}">${c.f(t[c.key])}</td>`).join('')}
    </tr>`).join('');

  const totRow=`<tr class="total-row">
    <td class="left" colspan="3">TOTAL</td>
    ${cols.map(c=>`<td>${c.f(grand[c.key])}</td>`).join('')}
  </tr>`;

  document.getElementById('tbl-wrap').innerHTML=
    `<table><thead>${head}</thead><tbody>${body}${totRow}</tbody></table>`;
}

// ── Theme ────────────────────────────────────────────────────────────────────
function toggleTheme(){
  const html=document.documentElement;
  const isLight=html.dataset.theme==='light';
  html.dataset.theme=isLight?'dark':'light';
  document.getElementById('theme-btn').textContent=isLight?'☀ Claro':'☾ Oscuro';
  localStorage.setItem('pnl-exec-theme',html.dataset.theme);
  if(chartInst) renderChart(ROWS);
}

async function init(){
  const saved=localStorage.getItem('pnl-exec-theme')||'dark';
  document.documentElement.dataset.theme=saved;
  document.getElementById('theme-btn').textContent=saved==='light'?'☾ Oscuro':'☀ Claro';
  await loadInitialOptions();
}
init();
</script>
</body>
</html>$seed$, $seed$Vista ejecutiva del P&L por Revenue Manager. Tarjetas por proyecto con semáforo de salud (BUENO/ALERTA/CRÍTICO), KPIs grandes, alertas de riesgo y tendencia Revenue vs Facturación.$seed$, $seed$replicon$seed$, $seed$shared$seed$, $seed${pnl_mensual}$seed$::text[], NOW())
ON CONFLICT (name) DO NOTHING;

INSERT INTO analytic_apps (name, title, html, description, cartridge_id, visibility, datasets_used, updated_at)
VALUES ($seed$pnl_revenue_manager$seed$, $seed$P&L por Revenue Manager$seed$, $seed$<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>P&L por Revenue Manager</title>
<script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
<style>
  :root{--bg:#0d1117;--bg2:#161b22;--border:#30363d;--text1:#e6edf3;--text2:#8b949e;--green:#39ff14;--blue:#7c9fff;--amber:#ffb300;--red:#f85149}
  [data-theme=light]{--bg:#f6f8fa;--bg2:#ffffff;--border:#d0d7de;--text1:#1f2328;--text2:#656d76;--green:#1a7f37;--blue:#0969da;--amber:#9a6700;--red:#cf222e}
  *{box-sizing:border-box;margin:0;padding:0}
  body{background:var(--bg);color:var(--text1);font-family:"Share Tech Mono",monospace,sans-serif;min-height:100vh;transition:background .2s,color .2s}
  h1{font-size:14px;letter-spacing:3px;color:var(--blue);padding:24px 28px 0}
  .subtitle{font-size:9px;color:var(--text2);letter-spacing:2px;padding:4px 28px 20px}
  .controls{padding:0 28px 20px;display:flex;gap:12px;align-items:center;flex-wrap:wrap}
  label{font-size:10px;color:var(--text2);white-space:nowrap}
  .ms-wrap{position:relative;min-width:160px}
  .ms-trigger{background:var(--bg2);border:1px solid var(--border);color:var(--text1);padding:6px 28px 6px 12px;font-size:11px;font-family:inherit;border-radius:4px;cursor:pointer;width:100%;text-align:left;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;display:block;position:relative}
  .ms-trigger::after{content:'▾';position:absolute;right:9px;top:50%;transform:translateY(-50%);color:var(--text2);font-size:10px;pointer-events:none}
  .ms-trigger.open,.ms-trigger:focus{outline:none;border-color:var(--blue)}
  .ms-dropdown{position:absolute;top:calc(100% + 3px);left:0;min-width:100%;background:var(--bg2);border:1px solid var(--blue);border-radius:4px;z-index:999;max-height:220px;overflow-y:auto;box-shadow:0 8px 24px rgba(0,0,0,.5);display:none}
  .ms-dropdown.open{display:block}
  .ms-search{width:100%;background:var(--bg);border:none;border-bottom:1px solid var(--border);color:var(--text1);padding:7px 10px;font-size:10px;font-family:inherit;outline:none}
  .ms-opt{display:flex;align-items:center;gap:7px;padding:6px 10px;cursor:pointer;font-size:10px;font-family:inherit}
  .ms-opt:hover{background:var(--bg)}
  .ms-opt input[type=checkbox]{accent-color:var(--blue);width:11px;height:11px;flex-shrink:0}
  .ms-actions{display:flex;gap:4px;padding:5px 8px;border-top:1px solid var(--border)}
  .ms-act{flex:1;background:transparent;border:1px solid var(--border);color:var(--text2);padding:3px;font-size:9px;font-family:inherit;border-radius:3px;cursor:pointer;letter-spacing:.5px}
  .ms-act:hover{border-color:var(--blue);color:var(--blue)}
  .btn-filter{background:var(--blue);border:none;color:#fff;padding:6px 18px;font-size:10px;font-family:inherit;border-radius:4px;cursor:pointer;letter-spacing:1px}
  .btn-filter:disabled{opacity:.5;cursor:not-allowed}
  .theme-btn{margin-left:auto;background:transparent;border:1px solid var(--border);color:var(--text2);padding:5px 12px;font-size:9px;font-family:inherit;border-radius:4px;cursor:pointer;letter-spacing:1px}
  .theme-btn:hover{border-color:var(--blue);color:var(--blue)}
  .kpis{display:flex;gap:14px;padding:0 28px 24px;flex-wrap:wrap}
  .kpi{background:var(--bg2);border:1px solid var(--border);border-radius:6px;padding:16px 20px;min-width:160px}
  .kpi-label{font-size:9px;color:var(--text2);letter-spacing:2px;margin-bottom:6px}
  .kpi-val{font-size:20px;color:var(--text1)}
  .kpi-val.pos{color:var(--green)}.kpi-val.neg{color:var(--red)}.kpi-val.neu{color:var(--blue)}
  .section{margin:0 28px 28px}
  .section-title{font-size:10px;letter-spacing:2px;color:var(--text2);border-bottom:1px solid var(--border);padding-bottom:8px;margin-bottom:14px}
  table{width:100%;border-collapse:collapse;font-size:10px}
  th{text-align:right;padding:7px 10px;color:var(--text2);font-size:9px;letter-spacing:1px;border-bottom:1px solid var(--border);white-space:nowrap}
  th.left{text-align:left}
  td{text-align:right;padding:6px 10px;border-bottom:1px solid #1e2430;white-space:nowrap}
  [data-theme=light] td{border-bottom:1px solid #e8ecf0}
  td.left{text-align:left;color:var(--text2)}
  tr:hover td{background:var(--bg2)}
  .pos-val{color:var(--green)}.neg-val{color:var(--red)}.neutral-val{color:var(--blue)}
  .placeholder{text-align:center;padding:80px 20px;color:var(--text2);font-size:11px;line-height:2.2}
  .spinner{display:inline-block;width:12px;height:12px;border:2px solid var(--border);border-top-color:var(--blue);border-radius:50%;animation:spin .7s linear infinite;vertical-align:middle;margin-right:6px}
  @keyframes spin{to{transform:rotate(360deg)}}
  .chart-wrap{background:var(--bg2);border:1px solid var(--border);border-radius:6px;padding:20px;margin-bottom:28px}
  canvas{max-height:280px}
  .row-count{font-size:9px;color:var(--text3);letter-spacing:1px;float:right;margin-top:-22px;padding-right:2px}
</style>
</head>
<body>
<h1>&#9638; P&amp;L POR REVENUE MANAGER</h1>
<div class="subtitle">CONSULTAS EN TIEMPO REAL &middot; GOLD TABLE pnl_mensual</div>

<div class="controls">
  <label>Revenue Manager:</label>
  <div class="ms-wrap" id="ms-rm"></div>
  <label>Año Fiscal:</label>
  <div class="ms-wrap" id="ms-yr"></div>
  <label>Cliente:</label>
  <div class="ms-wrap" id="ms-cl"></div>
  <label>Proyecto:</label>
  <div class="ms-wrap" id="ms-pr" style="min-width:200px"></div>
  <button class="btn-filter" id="btn-filter" onclick="applyFilter()">FILTRAR</button>
  <button class="theme-btn" id="theme-btn" onclick="toggleTheme()">☀ LIGHT</button>
</div>

<div id="placeholder" class="placeholder">
  Selecciona al menos un filtro y presiona <strong style="color:var(--blue)">FILTRAR</strong><br>
  <span style="font-size:9px;letter-spacing:1px">Año fiscal: marzo a febrero &mdash; AF2025 = mar-2025 a feb-2026</span>
</div>

<div id="main-content" style="display:none">
  <div id="kpis" class="kpis"></div>
  <div class="section">
    <div class="section-title">EVOLUCIÓN MENSUAL</div>
    <div class="chart-wrap"><canvas id="chart"></canvas></div>
  </div>
  <div class="section">
    <div class="section-title">RESUMEN POR MES</div>
    <div id="row-count-mes" class="row-count"></div>
    <div id="tbl-mes" style="overflow-x:auto"></div>
  </div>
  <div class="section">
    <div class="section-title">DESGLOSE POR PROYECTO</div>
    <div id="row-count-proj" class="row-count"></div>
    <div id="tbl-proj" style="overflow-x:auto"></div>
  </div>
</div>

<script>
let ROWS = [];
let chartInst = null;
const PROJ_LABEL = {};

const fmt  = n => n==null?'—':'$'+Number(n).toLocaleString('es-MX',{minimumFractionDigits:2,maximumFractionDigits:2});
const fmtH = n => n==null?'—':Number(n).toLocaleString('es-MX',{minimumFractionDigits:1,maximumFractionDigits:1})+' h';
const fmtP = n => n==null?'—':Number(n).toFixed(2)+'%';
const margColor = v => v==null?'':v>=20?'pos-val':v>=10?'neutral-val':'neg-val';
const kpiColor  = v => v==null?'':v>0?'pos':v<0?'neg':'neu';

function groupBy(arr,key){return arr.reduce((m,r)=>{(m[r[key]]=m[r[key]]||[]).push(r);return m;},{});}
function sumRows(rows){
  const financial=['revenue_usd','facturacion_mes_usd','wip_usd','costo_directo','costo_hundido','costo_total','margen_bruto_usd'];
  const hours=['horas_facturables','horas_totales'];
  const a={revenue_usd:null,facturacion_mes_usd:null,wip_usd:null,costo_directo:null,costo_hundido:null,costo_total:null,margen_bruto_usd:null,horas_facturables:null,horas_totales:null};
  const ready=rows.filter(r=>r.financial_status==='ready');
  financial.forEach(k=>a[k]=ready.length&&ready.every(r=>r[k]!=null)?ready.reduce((sum,r)=>sum+Number(r[k]),0):null);
  hours.forEach(k=>a[k]=rows.length&&rows.every(r=>r[k]!=null)?rows.reduce((sum,r)=>sum+Number(r[k]),0):null);
  a.margen_bruto_pct=a.revenue_usd?(a.margen_bruto_usd/a.revenue_usd*100):null;
  return a;
}

// ── Multi-select component ──────────────────────────────────────────────────
const MS={};
function msCreate(id,ph='Todos'){
  const w=document.getElementById(id);
  w.innerHTML=`<button class="ms-trigger" onclick="msToggle('${id}',event)">${ph}</button>
    <div class="ms-dropdown" id="${id}-dd">
      <input class="ms-search" placeholder="Buscar…" oninput="msRender('${id}',this.value)">
      <div id="${id}-list"></div>
      <div class="ms-actions">
        <button class="ms-act" onclick="msAll('${id}',true)">TODO</button>
        <button class="ms-act" onclick="msAll('${id}',false)">NINGUNO</button>
      </div>
    </div>`;
  MS[id]={selected:new Set(),options:[],ph};
  document.addEventListener('click',e=>{if(!w.contains(e.target))msClose(id);});
}
function msToggle(id,ev){
  if(ev) ev.stopPropagation();
  const dd=document.getElementById(id+'-dd'),btn=document.querySelector(`#${id} .ms-trigger`);
  const was=dd.classList.contains('open');
  Object.keys(MS).forEach(k=>msClose(k));
  if(!was){dd.classList.add('open');btn.classList.add('open');}
}
function msClose(id){
  document.getElementById(id+'-dd')?.classList.remove('open');
  document.querySelector(`#${id} .ms-trigger`)?.classList.remove('open');
}
function msSetOptions(id,opts,labelFn=null){
  MS[id].options=opts; MS[id].labelFn=labelFn; msRender(id,'');
}
function msRender(id,search){
  const {options,selected,labelFn}=MS[id];
  const fil=search?options.filter(o=>String(labelFn?labelFn(o):o).toLowerCase().includes(search.toLowerCase())):options;
  document.getElementById(id+'-list').innerHTML=fil.map(o=>{
    const lbl=labelFn?labelFn(o):o;
    const val=String(o);
    return `<label class="ms-opt"><input type="checkbox" value="${val}" ${selected.has(val)?'checked':''} onchange="msCheck('${id}','${val.replace(/'/g,"\\'")}',this.checked)"><span>${lbl}</span></label>`;
  }).join('');
}
function msCheck(id,val,chk){chk?MS[id].selected.add(val):MS[id].selected.delete(val);msLabel(id);msCascade(id);}
function msAll(id,sel){
  const s=MS[id].selected;
  sel?MS[id].options.forEach(o=>s.add(String(o))):s.clear();
  msRender(id,''); msLabel(id); msCascade(id);
}
function msCascade(id){
  if(id==='ms-rm'||id==='ms-yr'){clearTimeout(MS._t);MS._t=setTimeout(refreshClientesProyectos,400);}
  if(id==='ms-cl'){clearTimeout(MS._t2);MS._t2=setTimeout(refreshProyectos,400);}
}
function msLabel(id){
  const {selected,ph,options,labelFn}=MS[id];
  const btn=document.querySelector(`#${id} .ms-trigger`);
  if(!selected.size) btn.textContent=ph;
  else if(selected.size===1) btn.textContent=labelFn?labelFn([...selected][0]):[...selected][0];
  else btn.textContent=`${selected.size} seleccionados`;
}
function msGet(id){return[...MS[id].selected];}

// ── Selectors ──────────────────────────────────────────────────────────────────

async function loadInitialOptions(){
  msCreate('ms-rm','Todos'); msCreate('ms-yr','Selecciona...'); msCreate('ms-cl','Todos'); msCreate('ms-pr','Todos');

  try{
    const r=await fetch('/api/data/pnl_mensual/options?columns=revenue_manager');
    const opts=await r.json();
    msSetOptions('ms-rm', opts.revenue_manager||[]);
  }catch(e){}

  try{
    const r=await fetch('/api/data/pnl_mensual/query',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters:{},limit:5000,columns:['mes']})
    });
    const rows=await r.json();
    if(Array.isArray(rows)){
      const fys=[...new Set(rows.map(r=>fiscalYear(r.mes)).filter(Boolean))].sort().reverse();
      msSetOptions('ms-yr', fys, y=>`AF${y} (mar-${y}/feb-${y+1})`);
    }
  }catch(e){}

  await refreshClientesProyectos();
}

async function refreshClientesProyectos(){
  const rm=msGet('ms-rm'), yr=msGet('ms-yr').map(Number);
  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  try{
    const r=await fetch('/api/data/pnl_mensual/query',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:5000,columns:['cliente','proyecto','project_name']})
    });
    const rows=await r.json();
    if(!Array.isArray(rows)) return;
    rows.forEach(r=>{
      if(r.proyecto&&!PROJ_LABEL[r.proyecto])
        PROJ_LABEL[r.proyecto]=r.project_name?`${r.proyecto} — ${r.project_name}`:r.proyecto;
    });
    const cls=[...new Set(rows.map(r=>r.cliente).filter(Boolean))].sort();
    const prevCl=msGet('ms-cl'), prevPr=msGet('ms-pr');
    msSetOptions('ms-cl', cls);
    prevCl.forEach(v=>{if(cls.includes(v)) MS['ms-cl'].selected.add(v);}); msLabel('ms-cl');

    const clSel=msGet('ms-cl');
    const projRows=clSel.length?rows.filter(r=>clSel.includes(r.cliente)):rows;
    const prs=[...new Set(projRows.map(r=>r.proyecto).filter(Boolean))].sort();
    msSetOptions('ms-pr', prs, p=>PROJ_LABEL[p]||p);
    prevPr.forEach(v=>{if(prs.includes(v)) MS['ms-pr'].selected.add(v);}); msLabel('ms-pr');
  }catch(e){}
}

async function refreshProyectos(){
  const rm=msGet('ms-rm'),yr=msGet('ms-yr').map(Number),cl=msGet('ms-cl');
  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  if(cl.length) filters.cliente=cl.length===1?cl[0]:cl;
  try{
    const r=await fetch('/api/data/pnl_mensual/query',{method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:5000,columns:['proyecto','project_name']})});
    const rows=await r.json();
    if(!Array.isArray(rows)) return;
    rows.forEach(r=>{if(r.proyecto&&!PROJ_LABEL[r.proyecto])PROJ_LABEL[r.proyecto]=r.project_name?`${r.proyecto} — ${r.project_name}`:r.proyecto;});
    const prevPr=msGet('ms-pr');
    const prs=[...new Set(rows.map(r=>r.proyecto).filter(Boolean))].sort();
    msSetOptions('ms-pr',prs,p=>PROJ_LABEL[p]||p);
    prevPr.forEach(v=>{if(prs.includes(v))MS['ms-pr'].selected.add(v);}); msLabel('ms-pr');
  }catch(e){}
}

// ── Main query ─────────────────────────────────────────────────────────────────

async function applyFilter(){
  const rm=msGet('ms-rm'), yr=msGet('ms-yr').map(Number), cl=msGet('ms-cl'), pr=msGet('ms-pr');
  const filters={};
  if(rm.length) filters.revenue_manager=rm.length===1?rm[0]:rm;
  if(yr.length) filters.fiscal_year=yr.length===1?yr[0]:yr;
  if(cl.length) filters.cliente=cl.length===1?cl[0]:cl;
  if(pr.length) filters.proyecto=pr.length===1?pr[0]:pr;

  const btn=document.getElementById('btn-filter');
  btn.innerHTML='<span class="spinner"></span>Consultando...';
  btn.disabled=true;

  try{
    const r=await fetch('/api/data/pnl_mensual/query',{
      method:'POST',headers:{'Content-Type':'application/json'},
      body:JSON.stringify({filters,limit:5000})
    });
    ROWS=await r.json();
    if(!Array.isArray(ROWS)) ROWS=[];
    ROWS.forEach(r=>{
      if(r.proyecto&&!PROJ_LABEL[r.proyecto])
        PROJ_LABEL[r.proyecto]=r.project_name?`${r.proyecto} — ${r.project_name}`:r.proyecto;
    });
    document.getElementById('placeholder').style.display='none';
    document.getElementById('main-content').style.display='';
    render();
  }catch(e){
    alert('Error: '+e.message);
  }finally{
    btn.textContent='FILTRAR'; btn.disabled=false;
  }
}

// ── Render ─────────────────────────────────────────────────────────────────────

function render(){
  renderKPIs(ROWS);
  renderChart(ROWS);
  renderTblMes(ROWS);
  renderTblProj(ROWS);
}

function renderKPIs(rows){
  const t=sumRows(rows);
  document.getElementById('kpis').innerHTML=[
    ['REVENUE',fmt(t.revenue_usd),kpiColor(t.revenue_usd)],
    ['FACTURACIÓN',fmt(t.facturacion_mes_usd),'neu'],
    ['WIP',fmt(t.wip_usd),kpiColor(t.wip_usd)],
    ['COSTO TOTAL',fmt(t.costo_total),''],
    ['MARGEN BRUTO',fmt(t.margen_bruto_usd),kpiColor(t.margen_bruto_usd)],
    ['MARGEN %',fmtP(t.margen_bruto_pct),margColor(t.margen_bruto_pct)],
    ['HRS FACTURABLES',fmtH(t.horas_facturables),'neu'],
  ].map(([l,v,c])=>`<div class="kpi"><div class="kpi-label">${l}</div><div class="kpi-val ${c}">${v}</div></div>`).join('');
}

function renderChart(rows){
  const byMes=groupBy(rows,'mes');
  const meses=Object.keys(byMes).sort();
  const revenue=meses.map(m=>sumRows(byMes[m]).revenue_usd);
  const costo=meses.map(m=>sumRows(byMes[m]).costo_total);
  const margen=meses.map(m=>sumRows(byMes[m]).margen_bruto_usd);
  const labels=meses.map(m=>m?m.slice(0,7):m);
  if(chartInst)chartInst.destroy();
  const isLight=document.documentElement.dataset.theme==='light';
  const tickColor=isLight?'#656d76':'#8b949e';
  const gridColor=isLight?'#d0d7de':'#1e2430';
  const margenColor=isLight?'#1a7f37':'#39ff14';
  const ctx=document.getElementById('chart').getContext('2d');
  chartInst=new Chart(ctx,{
    type:'bar',
    data:{labels,datasets:[
      {label:'Revenue',data:revenue,backgroundColor:'rgba(124,159,255,.7)',borderRadius:3},
      {label:'Costo Total',data:costo,backgroundColor:'rgba(248,81,73,.5)',borderRadius:3},
      {label:'Margen Bruto',data:margen,type:'line',borderColor:margenColor,
       backgroundColor:isLight?'rgba(26,127,55,.08)':'rgba(57,255,20,.08)',tension:.3,pointRadius:3,fill:true},
    ]},
    options:{
      responsive:true,maintainAspectRatio:true,
      plugins:{legend:{labels:{color:tickColor,font:{size:10}}}},
      scales:{
        x:{ticks:{color:tickColor,font:{size:9}},grid:{color:gridColor}},
        y:{ticks:{color:tickColor,font:{size:9},callback:v=>'$'+Number(v/1000).toFixed(0)+'k'},grid:{color:gridColor}}
      }
    }
  });
}

function renderTblMes(rows){
  const byMes=groupBy(rows,'mes');
  const meses=Object.keys(byMes).sort();
  const metrics=[
    ['revenue_usd',      'Revenue USD',   fmt,  v=>kpiColor(v)],
    ['costo_directo',    'Costo Directo', fmt,  ()=>''],
    ['costo_hundido',    'Costo Hundido', fmt,  ()=>''],
    ['costo_total',      'Costo Total',   fmt,  ()=>''],
    ['margen_bruto_usd', 'Margen Bruto',  fmt,  v=>kpiColor(v)],
    ['margen_bruto_pct', 'Margen %',      fmtP, v=>margColor(v)],
    ['facturacion_mes_usd','Facturación', fmt,  ()=>''],
    ['wip_usd',          'WIP',           fmt,  v=>kpiColor(v)],
  ];
  const totals=meses.reduce((m,mes)=>{m[mes]=sumRows(byMes[mes]);return m;},{});
  const grand=sumRows(rows);
  document.getElementById('row-count-mes').textContent=`${meses.length} meses`;
  const head='<tr><th class="left" style="min-width:130px">Métrica</th>'+
    meses.map(m=>`<th>${m.slice(0,7)}</th>`).join('')+
    '<th style="color:var(--blue)">Total</th></tr>';
  const body=metrics.map(([k,label,f,colorFn])=>{
    const cells=meses.map(mes=>{
      const v=totals[mes][k];
      return `<td class="${colorFn(v)}">${f(v)}</td>`;
    }).join('');
    const vT=grand[k];
    return `<tr><td class="left" style="color:var(--text2);font-size:9px;letter-spacing:1px">${label}</td>${cells}<td class="${colorFn(vT)}" style="font-weight:bold">${f(vT)}</td></tr>`;
  }).join('');
  document.getElementById('tbl-mes').innerHTML=`<table><thead>${head}</thead><tbody>${body}</tbody></table>`;
}

function renderTblProj(rows){
  const byProj=groupBy(rows,'proyecto');
  const projs=Object.keys(byProj).sort();
  const cols=[
    ['revenue_usd',       'Revenue',     fmt,  v=>kpiColor(v)],
    ['costo_directo',     'C.Directo',   fmt,  ()=>''],
    ['costo_hundido',     'C.Hundido',   fmt,  ()=>''],
    ['costo_total',       'C.Total',     fmt,  ()=>''],
    ['margen_bruto_usd',  'Margen USD',  fmt,  v=>kpiColor(v)],
    ['margen_bruto_pct',  'Margen %',    fmtP, v=>margColor(v)],
    ['facturacion_mes_usd','Facturación',fmt,  ()=>''],
    ['wip_usd',           'WIP',         fmt,  v=>kpiColor(v)],
    ['pct_avance_real',   '% Avance',    fmtP, ()=>''],
  ];
  document.getElementById('row-count-proj').textContent=`${projs.length} proyectos`;
  const head='<tr><th class="left">Proyecto</th><th class="left">Cliente</th><th class="left">Tipo</th>'+
    cols.map(([k,l])=>`<th>${l}</th>`).join('')+'</tr>';
  const body=projs.map(proj=>{
    const rs=byProj[proj];
    const t=sumRows(rs);
    const r0=rs[0];
    const avance=rs.reduce((best,r)=>r.mes>(best.mes||'')?r:best,{}).pct_avance_real;
    const label=PROJ_LABEL[proj]||proj;
    const projId=String(proj).replace(/[^a-z0-9]/gi,'_');
    return `<tr style="cursor:pointer" onclick="toggleDrill('${proj}','${projId}',this)" title="Clic para ver consultores">`+
      `<td class="left" style="font-size:9px"><span id="arr-${projId}" style="display:inline-block;width:10px;color:var(--text3)">▸</span> ${label}</td>`+
      `<td class="left" style="font-size:9px">${r0.cliente||'—'}</td>`+
      `<td class="left" style="font-size:9px">${r0.tipo_proyecto||'—'}</td>`+
      cols.map(([k,l,f,colorFn])=>{
        const v=k==='pct_avance_real'?avance:t[k];
        return `<td class="${colorFn(v)}">${f(v)}</td>`;
      }).join('')+'</tr>'+
      `<tr id="drill-${projId}" style="display:none"><td colspan="${3+cols.length}" style="background:var(--bg2);padding:0"><div id="drill-body-${projId}" style="padding:8px 14px"></div></td></tr>`;
  }).join('');
  const grand=sumRows(rows);
  const totRow='<tr style="border-top:2px solid var(--blue);font-weight:bold">'+
    '<td class="left" style="font-size:9px;color:var(--blue)">TOTAL</td>'+
    '<td class="left"></td><td class="left"></td>'+
    cols.map(([k,l,f,colorFn])=>{
      if(k==='pct_avance_real') return '<td>—</td>';
      const v=grand[k];
      return `<td class="${colorFn(v)}">${f(v)}</td>`;
    }).join('')+'</tr>';
  document.getElementById('tbl-proj').innerHTML=`<table><thead>${head}</thead><tbody>${body}${totRow}</tbody></table>`;
}

// ── Theme ──────────────────────────────────────────────────────────────────────

function toggleTheme(){
  const html=document.documentElement;
  const isDark=html.dataset.theme!=='light';
  html.dataset.theme=isDark?'light':'dark';
  document.getElementById('theme-btn').textContent=isDark?'☾ DARK':'☀ LIGHT';
  localStorage.setItem('pnl-theme',html.dataset.theme);
  if(chartInst) renderChart(ROWS);
}

function fiscalYear(mesStr){
  const p=(mesStr||'').slice(0,7).split('-');
  const yr=parseInt(p[0])||0, mo=parseInt(p[1])||0;
  return mo<=2?yr-1:yr;
}

// ── Boot ───────────────────────────────────────────────────────────────────────

async function init(){
  const saved=localStorage.getItem('pnl-theme')||'dark';
  document.documentElement.dataset.theme=saved;
  document.getElementById('theme-btn').textContent=saved==='light'?'☾ DARK':'☀ LIGHT';
  await loadInitialOptions();
}

init();

async function toggleDrill(proj, projId, tr){
  event.stopPropagation();
  const drill = document.getElementById('drill-'+projId);
  const arr   = document.getElementById('arr-'+projId);
  if(drill.style.display !== 'none'){ drill.style.display='none'; arr.textContent='▸'; return; }
  arr.textContent='▾';
  drill.style.display='';
  const body = document.getElementById('drill-body-'+projId);
  body.innerHTML = '<div style="color:var(--text3);font-size:10px;padding:6px">Cargando consultores…</div>';
  const meses = [...new Set(ROWS.filter(r=>String(r.proyecto)===String(proj)).map(r=>String(r.mes).slice(0,10)))];
  const filters = { proyecto: proj };
  if(meses.length === 1) filters.mes = meses[0];
  else if(meses.length > 1) filters.mes = meses;
  try{
    const r = await fetch('/api/data/pnl_detalle_consultor/query',{
      method:'POST', headers:{'Content-Type':'application/json'},
      body: JSON.stringify({filters, limit: 5000})
    });
    let data = await r.json();
    if(!Array.isArray(data)) data = [];
    if(!data.length){ body.innerHTML = '<div style="color:var(--text3);font-size:10px;padding:6px">Sin actividad de consultores en el periodo filtrado.</div>'; return; }
    const byCon = {};
    data.forEach(r=>{
      const c = r.consultor || '—';
      if(!byCon[c]) byCon[c]={consultor:c, tipo_empleado:r.tipo_empleado, hrs_fact:0, hrs_nofact:0, hrs_tot:0, costo_dir:0, costo_hund:0, rev:0, costo_hora:r.costo_hora, billing_rate_usd:r.billing_rate_usd, financial_ready:true, missing:{}};
      const a=byCon[c];
      a.financial_ready = a.financial_ready && r.financial_status==='ready';
      [['hrs_fact','horas_facturables'],['hrs_nofact','horas_no_facturables'],['hrs_tot','horas_totales'],['costo_dir','costo_directo'],['costo_hund','costo_hundido_aporte'],['rev','revenue_aporte']].forEach(([dst,src])=>{
        if(r[src]==null) a.missing[dst]=true;
        else a[dst]+=Number(r[src]);
      });
    });
    const money=['costo_dir','costo_hund','rev'];
    const fields=['hrs_fact','hrs_nofact','hrs_tot',...money];
    const cons = Object.values(byCon).map(a=>{
      fields.forEach(k=>{if(a.missing[k]||(money.includes(k)&&!a.financial_ready))a[k]=null;});
      return a;
    }).sort((a,b)=>(b.rev??-Infinity)-(a.rev??-Infinity));
    const fH = n => n==null?'—':Number(n).toFixed(1)+'h';
    const fM = n => n==null?'—':'$'+Math.round(Number(n)).toLocaleString('en');
    const fR = n => n==null?'—':'$'+Number(n).toFixed(2)+'/h';
    const totals=Object.fromEntries(fields.map(k=>[k,cons.length&&cons.every(c=>c[k]!=null)?cons.reduce((sum,c)=>sum+Number(c[k]),0):null]));
    body.innerHTML = `
      <div style="font-size:9px;color:var(--text3);letter-spacing:1px;margin-bottom:6px">CONSULTORES — ${cons.length} · ${meses.length} mes(es)</div>
      <table style="width:100%;border-collapse:collapse;font-size:10px">
        <thead><tr style="background:var(--bg3)">
          <th class="left" style="text-align:left;padding:4px 8px">Consultor</th>
          <th class="left" style="text-align:left;padding:4px 8px">Tipo</th>
          <th style="text-align:right;padding:4px 8px">Hrs Fact</th>
          <th style="text-align:right;padding:4px 8px">Hrs No Fact</th>
          <th style="text-align:right;padding:4px 8px">Hrs Tot</th>
          <th style="text-align:right;padding:4px 8px">Tarifa</th>
          <th style="text-align:right;padding:4px 8px">Costo/h</th>
          <th style="text-align:right;padding:4px 8px">Costo Dir</th>
          <th style="text-align:right;padding:4px 8px">Hundido</th>
          <th style="text-align:right;padding:4px 8px">Revenue</th>
          <th style="text-align:right;padding:4px 8px">Margen</th>
        </tr></thead>
        <tbody>
          ${cons.map(c=>{
            const margen = money.every(k=>c[k]!=null)?c.rev-c.costo_dir-c.costo_hund:null;
            const mc = margen==null?'':margen>0?'pos':margen<0?'neg':'';
            return `<tr>
              <td class="left" style="padding:3px 8px">${c.consultor}</td>
              <td class="left" style="padding:3px 8px;color:var(--text3);font-size:9px">${c.tipo_empleado||'—'}</td>
              <td style="text-align:right;padding:3px 8px;color:var(--green)">${fH(c.hrs_fact)}</td>
              <td style="text-align:right;padding:3px 8px;color:var(--amber)">${fH(c.hrs_nofact)}</td>
              <td style="text-align:right;padding:3px 8px">${fH(c.hrs_tot)}</td>
              <td style="text-align:right;padding:3px 8px">${fR(c.billing_rate_usd)}</td>
              <td style="text-align:right;padding:3px 8px">${fR(c.costo_hora)}</td>
              <td style="text-align:right;padding:3px 8px">${fM(c.costo_dir)}</td>
              <td style="text-align:right;padding:3px 8px;color:var(--red)">${fM(c.costo_hund)}</td>
              <td style="text-align:right;padding:3px 8px;color:var(--green);font-weight:600">${fM(c.rev)}</td>
              <td class="${mc}" style="text-align:right;padding:3px 8px;font-weight:600">${fM(margen)}</td>
            </tr>`;
          }).join('')}
          <tr style="border-top:1px solid var(--border);font-weight:700">
            <td class="left" style="padding:4px 8px">TOTAL</td><td></td>
            <td style="text-align:right;padding:4px 8px">${fH(totals.hrs_fact)}</td>
            <td style="text-align:right;padding:4px 8px">${fH(totals.hrs_nofact)}</td>
            <td style="text-align:right;padding:4px 8px">${fH(totals.hrs_tot)}</td>
            <td></td><td></td>
            <td style="text-align:right;padding:4px 8px">${fM(totals.costo_dir)}</td>
            <td style="text-align:right;padding:4px 8px">${fM(totals.costo_hund)}</td>
            <td style="text-align:right;padding:4px 8px">${fM(totals.rev)}</td>
            <td style="text-align:right;padding:4px 8px">${fM(money.every(k=>totals[k]!=null)?totals.rev-totals.costo_dir-totals.costo_hund:null)}</td>
          </tr>
        </tbody>
      </table>`;
  }catch(e){
    body.innerHTML = `<div style="color:var(--red);font-size:10px;padding:6px">Error: ${e.message}</div>`;
  }
}
</script>
</body>
</html>$seed$, $seed$$seed$, $seed$replicon$seed$, $seed$shared$seed$, $seed${pnl_detalle_consultor,pnl_mensual}$seed$::text[], NOW())
ON CONFLICT (name) DO NOTHING;

INSERT INTO analytic_apps (name, title, html, description, cartridge_id, visibility, datasets_used, updated_at)
VALUES ($seed$timesheet_semanal$seed$, $seed$Hoja de Tiempo Semanal$seed$, $seed$<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<title>Hoja de Tiempo Semanal</title>
<style>
  :root {
    --bg: #fafafa; --bg2: #fff; --bg3: #f5f5f7; --border: #e0e0e5;
    --text: #1a1a1a; --text2: #4a4a4a; --text3: #888;
    --green: #2ea043; --red: #f85149; --amber: #e3b341; --blue: #7c9fff; --purple: #bc8cff;
    --font-ui: -apple-system,BlinkMacSystemFont,Segoe UI,Roboto,sans-serif;
    --font-mono: ui-monospace,SFMono-Regular,Menlo,Consolas,monospace;
  }
  body.dark {
    --bg:#0d1117; --bg2:#161b22; --bg3:#1c2128; --border:#30363d;
    --text:#e6edf3; --text2:#c9d1d9; --text3:#7d8590;
  }
  body { background:var(--bg); color:var(--text); font-family:var(--font-ui); margin:0; padding:24px; font-size:12px; }
  h1 { font-size:18px; margin:0 0 4px; color:var(--purple); letter-spacing:1px; }
  .sub { color:var(--text3); font-size:11px; margin-bottom:20px; }
  .toolbar { display:flex; gap:14px; align-items:center; padding-bottom:14px; border-bottom:1px solid var(--border); margin-bottom:18px; flex-wrap:wrap; }
  .fld { display:flex; align-items:center; gap:6px; }
  .fld label { font-size:10px; color:var(--text3); letter-spacing:1px; text-transform:uppercase; }
  select { background:var(--bg2); color:var(--text); border:1px solid var(--border); padding:5px 10px; font-family:var(--font-ui); font-size:11px; border-radius:3px; min-width:180px; }
  button { background:var(--purple); color:#fff; border:0; padding:6px 14px; font-size:11px; font-weight:600; letter-spacing:.5px; border-radius:3px; cursor:pointer; }
  button:hover { opacity:.9; }
  button.theme { background:transparent; color:var(--text2); border:1px solid var(--border); }
  #placeholder { color:var(--text3); padding:60px; text-align:center; font-size:13px; }
  .mes-block { background:var(--bg2); border:1px solid var(--border); border-radius:4px; margin-bottom:16px; overflow:hidden; }
  .mes-head {
    background:var(--bg3); padding:8px 14px; font-size:11px; font-weight:600;
    color:var(--purple); letter-spacing:1px; text-transform:uppercase;
    display:flex; justify-content:space-between; align-items:center;
    cursor:pointer; user-select:none;
  }
  .mes-totals { color:var(--text2); font-size:10px; font-weight:500; letter-spacing:0; text-transform:none; }
  .mes-totals span { margin-left:14px; }
  .mes-totals b { color:var(--text); }
  table { border-collapse:collapse; width:100%; font-size:10px; }
  th { background:var(--bg3); padding:6px 10px; text-align:left; font-weight:600; color:var(--text2); border-bottom:1px solid var(--border); }
  th.num { text-align:right; min-width:62px; }
  td { padding:5px 10px; border-bottom:1px solid var(--border); color:var(--text2); }
  td.num { text-align:right; font-family:var(--font-mono); }
  td.num.zero { color:var(--text3); opacity:.5; }
  td.proj { font-weight:500; color:var(--text); }
  td.semana { color:var(--text3); font-size:9px; padding-left:24px; }
  tr.semana-row td { background:var(--bg); }
  tr.proj-row { font-weight:600; background:var(--bg3); }
  tr.proj-row td.proj { color:var(--text); }
  tr.tot-row td { background:var(--bg3); font-weight:700; color:var(--purple); border-top:2px solid var(--border); }
  .arrow { display:inline-block; width:10px; color:var(--text3); margin-right:4px; }
</style>
</head>
<body>

<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:14px;margin-bottom:6px">
  <div>
    <h1>◇ HOJA DE TIEMPO — SEMANAL</h1>
    <div class="sub">Gold · consultor_timesheet_semanal · Año fiscal mar–feb</div>
  </div>
  <button class="theme" onclick="toggleTheme()">☾ Oscuro</button>
</div>

<div class="toolbar">
  <div class="fld">
    <label>Año Fiscal</label>
    <select id="f-af"></select>
  </div>
  <div class="fld">
    <label>Consultor</label>
    <select id="f-con"><option value="">(elige uno)</option></select>
  </div>
  <button onclick="load()">Ver hoja</button>
</div>

<div id="placeholder">Selecciona consultor y año fiscal para ver su hoja de tiempo.</div>
<div id="content"></div>

<script>
const MO=['','Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
const fmtH = n => n==null||+n===0 ? '—' : (+n).toFixed(1)+'h';
const fmtMes = m => { const p=String(m).slice(0,7).split('-'); return `${MO[parseInt(p[1])]} ${p[0]}`; };
const fmtSem = s => { const d=new Date(s); return `Sem ${d.getDate().toString().padStart(2,'0')} ${MO[d.getMonth()+1]}`; };
function fiscalYear(s){ const p=(s||'').slice(0,7).split('-'); const y=+p[0]||0, mo=+p[1]||0; return mo<=2 ? y-1 : y; }

function toggleTheme(){
  document.body.classList.toggle('dark');
  const btn=document.querySelector('.theme');
  btn.textContent = document.body.classList.contains('dark') ? '☀ Claro' : '☾ Oscuro';
}

async function loadOptions(){
  const r = await fetch('/api/data/consultor_timesheet_semanal/options?columns=consultor,mes');
  const o = await r.json();
  const cons = (o.consultor||[]).sort();
  const sel = document.getElementById('f-con');
  cons.forEach(c => sel.innerHTML += `<option value="${c}">${c}</option>`);

  const meses = (o.mes||[]).map(m => String(m).slice(0,7)).filter(Boolean);
  const afs = [...new Set(meses.map(m => fiscalYear(m)))].sort((a,b)=>b-a);
  const afSel = document.getElementById('f-af');
  afs.forEach(y => afSel.innerHTML += `<option value="${y}">AF${y} (mar ${y} – feb ${y+1})</option>`);
}

async function load(){
  const con = document.getElementById('f-con').value;
  const af  = +document.getElementById('f-af').value;
  if(!con){ alert('Elige un consultor'); return; }

  const r = await fetch('/api/data/consultor_timesheet_semanal/query',{
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({filters:{consultor:con}, limit:20000})
  });
  let rows = await r.json();
  if(!Array.isArray(rows)) rows=[];
  rows = rows.filter(r => fiscalYear(r.mes) === af);

  document.getElementById('placeholder').style.display = rows.length ? 'none' : '';
  const c = document.getElementById('content');
  if(!rows.length){ c.innerHTML=''; return; }

  // Group by mes → proyecto → semana
  const byMes = {};
  rows.forEach(r => {
    const mk = String(r.mes).slice(0,10);
    if(!byMes[mk]) byMes[mk] = {};
    const pk = r.proyecto + '|' + (r.project_name||'');
    if(!byMes[mk][pk]) byMes[mk][pk] = {};
    const sk = String(r.semana).slice(0,10);
    if(!byMes[mk][pk][sk]) byMes[mk][pk][sk] = {tot:0, fact:0, nfact:0};
    byMes[mk][pk][sk].tot   += +r.horas_total||0;
    byMes[mk][pk][sk].fact  += +r.horas_facturables||0;
    byMes[mk][pk][sk].nfact += +r.horas_no_facturables||0;
  });

  let html = '';
  const meses = Object.keys(byMes).sort();
  meses.forEach((mk, idx) => {
    const proys = byMes[mk];
    // Mes totals + unique semanas
    const semSet = new Set();
    let mTot=0, mFact=0, mNfact=0;
    Object.values(proys).forEach(s => Object.entries(s).forEach(([sk,v])=>{ semSet.add(sk); mTot+=v.tot; mFact+=v.fact; mNfact+=v.nfact; }));
    const semanas = [...semSet].sort();

    html += `<div class="mes-block">
      <div class="mes-head" onclick="toggleMes(${idx})">
        <div><span class="arrow" id="arr-${idx}">▾</span>${fmtMes(mk)}</div>
        <div class="mes-totals">
          <span>Total <b>${fmtH(mTot)}</b></span>
          <span style="color:var(--green)">Fact. <b>${fmtH(mFact)}</b></span>
          <span style="color:var(--amber)">No fact. <b>${fmtH(mNfact)}</b></span>
        </div>
      </div>
      <div id="body-${idx}"><table><thead><tr>
        <th style="min-width:280px">Proyecto / Semana</th>
        ${semanas.map(s => `<th class="num">${fmtSem(s)}</th>`).join('')}
        <th class="num">Total</th>
        <th class="num" style="color:var(--green)">Fact.</th>
        <th class="num" style="color:var(--amber)">No fact.</th>
      </tr></thead><tbody>`;

    // Project totals
    const projOrder = Object.keys(proys).sort((a,b)=>{
      const ta=Object.values(proys[a]).reduce((x,v)=>x+v.tot,0);
      const tb=Object.values(proys[b]).reduce((x,v)=>x+v.tot,0);
      return tb-ta;
    });
    projOrder.forEach(pk => {
      const [code, name] = pk.split('|');
      const sems = proys[pk];
      let pTot=0, pFact=0, pNfact=0;
      Object.values(sems).forEach(v=>{ pTot+=v.tot; pFact+=v.fact; pNfact+=v.nfact; });
      html += `<tr class="proj-row">
        <td class="proj">${code}${name?' — '+name:''}</td>
        ${semanas.map(s => {
          const v = sems[s];
          return `<td class="num ${v?'':'zero'}">${v?fmtH(v.tot):'—'}</td>`;
        }).join('')}
        <td class="num">${fmtH(pTot)}</td>
        <td class="num" style="color:var(--green)">${fmtH(pFact)}</td>
        <td class="num" style="color:var(--amber)">${fmtH(pNfact)}</td>
      </tr>`;
    });

    // Mes total
    html += `<tr class="tot-row">
      <td class="proj">TOTAL ${fmtMes(mk).toUpperCase()}</td>
      ${semanas.map(s => {
        let st=0; Object.values(proys).forEach(p=>{ if(p[s]) st+=p[s].tot; });
        return `<td class="num ${st===0?'zero':''}">${fmtH(st)}</td>`;
      }).join('')}
      <td class="num">${fmtH(mTot)}</td>
      <td class="num" style="color:var(--green)">${fmtH(mFact)}</td>
      <td class="num" style="color:var(--amber)">${fmtH(mNfact)}</td>
    </tr>`;

    html += `</tbody></table></div></div>`;
  });

  c.innerHTML = html;
}

function toggleMes(idx){
  const body = document.getElementById('body-'+idx);
  const arr  = document.getElementById('arr-'+idx);
  if(body.style.display === 'none'){ body.style.display=''; arr.textContent='▾'; }
  else { body.style.display='none'; arr.textContent='▸'; }
}

loadOptions();
</script>
</body>
</html>
$seed$, $seed$$seed$, $seed$replicon$seed$, $seed$shared$seed$, $seed${consultor_timesheet_semanal}$seed$::text[], NOW())
ON CONFLICT (name) DO NOTHING;
